            ESPChamsFillTransparency = 0.6, ESPChamsOutlineTransparency = 0, ESPChamsVisSplit = true,
            ESPBoxTransparency = 0, ESPBoxFillTransparency = 0.75, ESPNameTransparency = 0,
            ESPHealthTransparency = 0.1, ESPSkeletonTransparency = 0.2, ESPTracerTransparency = 0.35,
            ESPHeadDotTransparency = 0, ESPNameMode = "Display", ESPFadeIn = true,
