    do
        local function __modImpl()
            __ANTIBRAIN_MODULES.g()

            local Services = __ANTIBRAIN_MODULES.k()

            local PRESET_ORDER = {
                'Underground Glitch', 'Orbit', 'Tweaking', 'Kicking Feet',
                'Low Cortisol', 'Floss', 'Take the L', 'Upside Down',
                'Michael Myers Shake', 'Headless', 'Wall Peek L', 'Glitch Through', 'Spin',
            }
            local PRESETS = {
                ['Underground Glitch']  = '138847307095534',
                ['Orbit']               = '133811691098518',
                ['Tweaking']            = '114353590132838',
                ['Kicking Feet']        = '131879764029003',
                ['Low Cortisol']        = '125822752810863',
                ['Floss']               = '72174079036035',
                ['Take the L']          = '112884830175040',
                ['Upside Down']         = '128616002281906',
                ['Michael Myers Shake'] = '123682198526131',
                ['Headless']            = '74738520664045',
                ['Wall Peek L']         = '123671647250039',
                ['Glitch Through']      = '85364072005108',
                ['Spin']                = '97064653080056',
            }

            local function animatorOf(character)
                if not character then return nil end
                local humanoid = character:FindFirstChildOfClass('Humanoid')
                if not humanoid then return nil end
                local animator = humanoid:FindFirstChildOfClass('Animator')
                if not animator then
                    animator = Instance.new('Animator')
                    animator.Parent = humanoid
                end
                return animator
            end
            local function resolveAnimation(id)
                local ok, objects = pcall(function()
                    return game:GetObjects('rbxassetid://' .. id)
                end)
                if ok and objects and #objects > 0 then
                    for _, object in ipairs(objects) do
                        if object:IsA('Animation') and object.AnimationId ~= '' then
                            return object
                        end
                    end
                    for _, object in ipairs(objects) do
                        for _, descendant in ipairs(object:GetDescendants()) do
                            if descendant:IsA('Animation') and descendant.AnimationId ~= '' then
                                return descendant
                            end
                        end
                    end
                end
                local animation = Instance.new('Animation')
                animation.AnimationId = 'rbxassetid://' .. id
                return animation
            end

            local function stopAll(emote)
                for _, track in ipairs(emote.tracks) do
                    pcall(function()
                        track:Stop(0)
                        track:Destroy()
                    end)
                end
                table.clear(emote.tracks)
            end

            local function loadTrack(character, id, speed, loop)
                if not character or id == '' then return nil end
                local animator = animatorOf(character)
                if not animator then return nil end
                local animation = resolveAnimation(id)
                local ok, track = pcall(function()
                    return animator:LoadAnimation(animation)
                end)
                if not ok or not track then
                    pcall(function() animation:Destroy() end)
                    return nil
                end
                track.Looped = loop
                track.Priority = Enum.AnimationPriority.Action4
                track:Play(0.1, 1, speed)
                return track
            end

            local function playEverywhere(emote)
                stopAll(emote)
                if not emote.enabled or emote.animationId == '' then return end
                local player = Services.Players.LocalPlayer
                local character = player.Character
                if character then
                    local track = loadTrack(character, emote.animationId, emote.speed, emote.loop)
                    if track then table.insert(emote.tracks, track) end
                end
                local live = Services.Workspace:FindFirstChild('Live')
                if live then
                    local scene = live:FindFirstChild(player.Name)
                    if scene then
                        local track = loadTrack(scene, emote.animationId, emote.speed, emote.loop)
                        if track then table.insert(emote.tracks, track) end
                    end
                end
            end

            local function setPreset(emote, name)
                emote.preset = name
                emote.animationId = PRESETS[name] or ''
            end

            local EmoteTab = {}

            EmoteTab.PRESET_ORDER = PRESET_ORDER

            function EmoteTab.build(ui)
                local tab = ui.tab('emote')

                local emote = {
                    enabled = false,
                    animationId = '',
                    loop = true,
                    speed = 2,
                    spawnProof = true,
                    preset = PRESET_ORDER[1],
                    tracks = {},
                }

                emote.play = function() playEverywhere(emote) end
                emote.stop = function() stopAll(emote) end

                local presetBox = tab:groupbox('Left', 'presets')
                local enabled = presetBox:toggle(ui.id('emote-enabled'), {
                    text = 'enabled',
                    default = false,
                })
                local preset = presetBox:dependent(function()
                    return enabled.value
                end):dropdown(ui.id('emote-preset'), {
                    text = 'preset',
                    values = table.clone(PRESET_ORDER),
                    default = PRESET_ORDER[1],
                })
                local customInput = presetBox:input(ui.id('emote-custom-id'), {
                    text = 'custom asset id',
                    placeholder = '1234567890',
                })
                local playCustom = presetBox:button({
                    text = 'play custom id',
                    callback = function()
                        local id = customInput.value:match('%d+')
                        if not id then return end
                        emote.preset = nil
                        emote.animationId = id
                        emote.enabled = true
                        enabled:set(true)
                        playEverywhere(emote)
                    end,
                })

                local speedBox = tab:groupbox('Right', 'speed')
                local speed = speedBox:slider(ui.id('emote-speed'), {
                    text = 'speed',
                    default = 2,
                    min = 1,
                    max = 100,
                    rounding = 0,
                    suffix = 'x',
                })

                local optionsBox = tab:groupbox('Right', 'options')
                local loop = optionsBox:toggle(ui.id('emote-loop'), {
                    text = 'loop',
                    default = true,
                })
                local spawnProof = optionsBox:toggle(ui.id('emote-spawn-proof'), {
                    text = 'spawn proof',
                    default = true,
                })
                local stopButton = optionsBox:button({
                    text = 'stop emote',
                    callback = function()
                        emote.enabled = false
                        enabled:set(false)
                        stopAll(emote)
                    end,
                })

                enabled:onChanged(function(value)
                    emote.enabled = value
                    if value then
                        if emote.animationId == '' then
                            setPreset(emote, emote.preset or PRESET_ORDER[1])
                        end
                        playEverywhere(emote)
                    else
                        stopAll(emote)
                    end
                end)
                preset:onChanged(function(value)
                    if value then
                        setPreset(emote, value)
                        if emote.enabled then playEverywhere(emote) end
                    end
                end)
                speed:onChanged(function(value)
                    emote.speed = value
                    for _, track in ipairs(emote.tracks) do
                        pcall(function() track:AdjustSpeed(value) end)
                    end
                end)
                loop:onChanged(function(value)
                    emote.loop = value
                    for _, track in ipairs(emote.tracks) do
                        track.Looped = value
                    end
                end)
                spawnProof:onChanged(function(value)
                    emote.spawnProof = value
                end)

                setPreset(emote, PRESET_ORDER[1])

                return emote
            end

            return table.freeze(EmoteTab)
        end

