            local Preview = {}

            Preview.KINDS = table.freeze({
                'wrap',
                'charm',
            })

            function Preview.new(run)
                local previews = {
                    run = run,
                    views = {
                        wrap = {},
                        charm = {},
                    },
                    parts = nil,
                }

                run:add(function()
                    table.clear(previews.views.wrap)
                    table.clear(previews.views.charm)
                end)

                return previews
