-- ── helpers ────────────────────────────────────────────────
local function addColorBlock(parent, idPrefix, label, modes, defaults)
    local result = {}
    result.mode = parent:dropdown(ui.id('esp-' .. idPrefix .. '-color-mode'), {
        text    = label .. ' colour',
        values  = modes,
        default = modes[1],
    })
    local modeVal = function() return result.mode.value end
    if defaults.solid then
        result.solid = parent:dependent(function() return modeVal() == 'Solid' end)
            :label(label):color(ui.id('esp-' .. idPrefix .. '-color'), { default = defaults.solid })
    end
    if defaults.a or defaults.b then
        local grad = parent:dependent(function() return modeVal() == 'Gradient' end)
        if defaults.a then
            result.gradA = grad:label(label .. ' A'):color(ui.id('esp-' .. idPrefix .. '-color-a'), { default = defaults.a })
        end
        if defaults.b then
            result.gradB = grad:label(label .. ' B'):color(ui.id('esp-' .. idPrefix .. '-color-b'), { default = defaults.b })
        end
    end
    return result
end

