local legacyTab = context.ui.tab('arch legacy')
local legacyLeft  = legacyTab:groupbox('Left',  'legacy arch engine')
local legacyRight = legacyTab:groupbox('Right', 'instructions')

local legacyState = {
    Running = false,
    Path    = 'arch/legacy_arch.lua',
    Thread  = nil,
}

local function legacyFileOk()
    local ok, exists = pcall(function()
        return type(isfile) == 'function' and isfile(legacyState.Path)
    end)
    return ok and exists
end

local function legacySizeKb()
    local ok, size = pcall(function()
        if type(readfile) ~= 'function' then return 0 end
        if not legacyFileOk() then return 0 end
        return #readfile(legacyState.Path)
    end)
    return math.floor(((ok and size) or 0) / 1024)
end

local function legacyStart()
    if legacyState.Running then
        context.ui.notify('legacy arch is already running')
        return
    end
    if type(isfile) ~= 'function' or type(readfile) ~= 'function' then
        context.ui.notify('executor is missing isfile/readfile')
        return
    end
    if not legacyFileOk() then
        context.ui.notify('missing ' .. legacyState.Path)
        return
    end
    local okRead, src = pcall(readfile, legacyState.Path)
    if not okRead or type(src) ~= 'string' or #src < 100 then
        context.ui.notify('read failed')
        return
    end
    local loader = loadstring or load
    if type(loader) ~= 'function' then
        context.ui.notify('executor is missing loadstring')
        return
    end
    local okC, chunk, err = pcall(loader, src, '=arch/legacy_arch.lua')
    if not okC or type(chunk) ~= 'function' then
        context.ui.notify('compile failed: ' .. tostring(err or chunk))
        return
    end
    legacyState.Running = true
    legacyState.Thread  = task.spawn(function()
        local okRun, runErr = pcall(chunk)
        legacyState.Running = false
        if not okRun then
            context.ui.notify('legacy arch error: ' .. tostring(runErr))
        else
            context.ui.notify('legacy arch exited')
        end
    end)
    context.ui.notify('legacy arch started · press Insert for its own UI')
end

local function legacyStatus()
    if not legacyFileOk() then
        context.ui.notify('file missing: ' .. legacyState.Path)
        return
    end
    context.ui.notify(string.format(
        'legacy · %s · %d KB · %s',
        legacyState.Path,
        legacySizeKb(),
        legacyState.Running and 'running' or 'stopped'
    ))
end

legacyLeft:button({
    text = 'check legacy_arch.lua',
    callback = function() legacyStatus() end,
})
legacyLeft:button({
