local archDeflecting = {}
svc.Players.PlayerRemoving:Connect(function(p)
    archDeflecting[p] = nil
end)

local function archUpdateDeflection()
    if not archFighters or not archFighters.Objects then return end
    for _, fo in archFighters.Objects do
        local p = fo.Player
        if not p then continue end
        if not fo.Entity or not fo.Entity:IsAlive() or fo:Get("IsSpectating") then
            archDeflecting[p] = false
            continue
        end
        local eq = fo.EquippedItem
        local isKatana = eq and eq.ViewModel and eq.ViewModel.Name == "Katana"
        archDeflecting[p] = isKatana
            and (eq._attack_cooldown and eq._attack_cooldown > tick())
            or false
    end
end

local function archIsEnemy(targetPlayer)
    if targetPlayer == archPlayer then return false end
    local pt = targetPlayer:GetAttribute("TeamID")
    local lt = archPlayer:GetAttribute("TeamID")
    if pt and lt then return pt ~= lt end
    return true
end

local function archHasKnifeViewModel(targetPlayer)
    if not targetPlayer then return false end
    local vms = archWs:FindFirstChild("ViewModels")
    if not vms then return false end
    for _, m in vms:GetChildren() do
        if m:IsA("Model")
            and string.find(m.Name, targetPlayer.Name, 1, true)
            and string.find(m.Name, "Knife", 1, true) then
            return true
        end
    end
    return false
end

local function archGetClosestTarget(teamFilter)
    local char = archPlayer.Character
    if not char then return nil, nil, nil end
    local myRoot = char:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil, nil, nil end
    local bestPlayer, bestRoot, bestHead, bestDist = nil, nil, nil, 500
    for _, p in svc.Players:GetPlayers() do
        if teamFilter and not archIsEnemy(p) then continue end
        if not teamFilter and p == archPlayer then continue end
        local pc = p.Character
        if pc then
            local pr = pc:FindFirstChild("HumanoidRootPart")
            local ph = pc:FindFirstChild("Head")
            local hm = pc:FindFirstChildWhichIsA("Humanoid")
            if pr and ph and hm and hm.Health > 0 then
                local d = (myRoot.Position - pr.Position).Magnitude
                if d < bestDist then
                    bestDist = d
                    bestPlayer = p
                    bestRoot = pr
                    bestHead = ph
                end
            end
        end
    end
    return bestPlayer, bestRoot, bestHead
end

local archVelHistory = {}
local function archRecordVelocity(char, root)
    local now, pos = tick(), root.Position
    if not archVelHistory[char] then
        archVelHistory[char] = {
            { pos = pos, t = now },
            { pos = pos, t = now },
        }
    else
        archVelHistory[char][1] = archVelHistory[char][2]
        archVelHistory[char][2] = { pos = pos, t = now }
    end
end

local function archPredictPosition(char, root, lead)
    local h = archVelHistory[char]
    if not h then return root.Position end
    local dt = h[2].t - h[1].t
    if dt < 0.001 then return root.Position end
    local vel = (h[2].pos - h[1].pos) / dt
    return root.Position + vel * lead
end

local function archKillVel(char)
    for _, p in ipairs(char:GetDescendants()) do
        if p:IsA("BasePart") then
            p.Velocity = Vector3.zero
            p.AssemblyLinearVelocity = Vector3.zero
            p.AssemblyAngularVelocity = Vector3.zero
        end
    end
end

local archCDFields = {
    "Cooldown", "AttackCooldown", "UseDelay", "SpinCooldown",
    "HeavyAttackCooldown", "AbilityCooldown", "FireCooldown", "DashCooldown",
}
local function archZeroCDs()
    task.spawn(function()
        local lib = archRepS:FindFirstChild("Modules")
        lib = lib and lib:FindFirstChild("ItemLibrary")
        if lib then
            local ok, t = pcall(require, lib)
            if ok and type(t) == "table" then
                local items = t.Items or t.Weapons or t.Melee
                if type(items) == "table" then
                    for _, item in pairs(items) do
                        if type(item) == "table" then
                            local isM = item.Type == "Melee"
                                or item.Category == "Melee"
                                or (item.Damage and not item.AmmoType)
                            if isM then
                                for _, f in ipairs(archCDFields) do
                                    if item[f] ~= nil then item[f] = 0 end
                                end
                            end
                        end
                    end
                end
            end
        end
    end)
    local char = archPlayer.Character
    if char then
        for _, v in ipairs(char:GetDescendants()) do
            for _, fn in ipairs(archCDFields) do
                if v.Name == fn
                    and (v:IsA("NumberValue") or v:IsA("IntValue")) then
                    v.Value = 0
                end
            end
        end
    end
end

