local archItemCache = {}
local function archRefreshItemCache()
    archItemCache = {}
    if not archFighters then return end
    local lf = archFighters.LocalFighter
    if not lf then return end
    if lf.Items then
        for i = 1, 3 do
            local item = lf.Items[i]
            if item then archItemCache[i] = item end
        end
        return
    end
    for i = 1, 3 do
        pcall(function() lf:EquipItem(i) end)
        task.wait(0.05)
        local item = lf.EquippedItem
        if item then archItemCache[i] = item end
    end
end

local function archItemCategory(idx)
    if idx == 1 then return "Primary"
    elseif idx == 2 then return "Secondary"
    elseif idx == 3 then return "Melee" end
    return nil
end

local function archIsCategoryEnabled(cat)
    if cat == "Primary"   then return archRageCfg.WeaponPrimary end
    if cat == "Secondary" then return archRageCfg.WeaponSecondary end
    if cat == "Melee"     then return archRageCfg.WeaponMelee end
    return false
end

local function archGetFirstEnabledSlot()
    if archRageCfg.WeaponPrimary   then return 1 end
    if archRageCfg.WeaponSecondary then return 2 end
    if archRageCfg.WeaponMelee     then return 3 end
    return 3
end

local function archReadItemValue(item, key)
    if not item then return nil end
    if type(item.Get) == "function" then
        local ok, v = pcall(item.Get, item, key)
        if ok then return v end
    end
    return item[key]
end

local function archItemObjectId(item)
    local data = item.Data
    return data and data.ObjectID or nil
end

local function archItemIsReloading(item)
    local now = tick()
    local cd = item._reload_cooldown
    if type(cd) == "number" and now < cd then return true end
    local noAmmo = item._shoot_cooldown_no_ammo
    return type(noAmmo) == "number" and now < noAmmo
end

local function archEquipItemByIndex(item, index)
    if not item then return end
    if item.IsEquipped then return end
    local fighter = item.ClientFighter
    if fighter and type(fighter.EquipItem) == "function" then
        pcall(fighter.EquipItem, fighter, index)
    end
end

local function archReloadItem(item)
    if not item then return end
    if archItemIsReloading(item) then return end
    local reserve = archReadItemValue(item, "AmmoReserve")
    if type(reserve) == "number" and reserve <= 0 then return end
    local maxAmmo = archReadItemValue(item, "Info.MaxAmmo")
        or archReadItemValue(item, "MaxAmmo")
    local ammo = archReadItemValue(item, "Ammo")
    if maxAmmo and ammo and ammo >= maxAmmo then return end
    local remote = archRepS:FindFirstChild("Remotes")
    remote = remote and remote:FindFirstChild("Replication")
    remote = remote and remote:FindFirstChild("Fighter")
    remote = remote and remote:FindFirstChild("UseItem")
    if not remote or not archEnums then return end
    local startRld = archEnums:ToEnum("StartReloading")
    local reload   = archEnums:ToEnum("Reload")
    if not startRld or not reload then return end
    pcall(function()
        remote:FireServer(
            archItemObjectId(item),
            startRld,
            { ["\1"] = reload, ["\2"] = reload },
            nil
        )
    end)
end

local function archGetAction()
    if not archFighters then return nil end
    local lf = archFighters.LocalFighter
    if not lf then return nil end
    local items = lf.Items
    if type(items) ~= "table" then return nil end
    local onEmpty = archRageCfg.OnEmpty
    local bestAttack, bestAttackPri, bestAttackIdx = nil, math.huge, nil
    local bestSwap,   bestSwapPri,   bestSwapIdx   = nil, math.huge, nil
    local anyEnabled = false
    for slotKey, item in next, items do
        if type(item) == "table" then
            local cat = archItemCategory(slotKey)
            if cat and archIsCategoryEnabled(cat) then
                anyEnabled = true
                local prio = 1
                local itType = item.Info and item.Info.Type or "Gun"
                local ammo = archReadItemValue(item, "Ammo")
                if itType == "Gun" and (ammo == nil or ammo == 0) then
                    local reserve = archReadItemValue(item, "AmmoReserve")
                    if reserve and reserve > 0 then
                        if onEmpty == "Reload" then
                            if prio < bestAttackPri then
                                bestAttack = item
                                bestAttackPri = prio
                                bestAttackIdx = slotKey
                            end
                        else
                            if prio < bestSwapPri then
                                bestSwap = item
                                bestSwapPri = prio
                                bestSwapIdx = slotKey
                            end
                        end
                    end
                elseif bestAttack == nil or prio < bestAttackPri then
                    bestAttack = item
                    bestAttackPri = prio
                    bestAttackIdx = slotKey
                end
            end
        end
    end
    if not anyEnabled then return nil end
    if bestAttack == nil then
        if onEmpty == "Swap" or bestSwap == nil then return nil end
        if bestSwap.IsEquipped then
            return { type = "Reload", item = bestSwap, index = bestSwapIdx }
        else
            return { type = "Swap",   item = bestSwap, index = bestSwapIdx }
        end
    end
    if not bestAttack.IsEquipped then
        return { type = "Swap", item = bestAttack, index = bestAttackIdx }
    end
    local ammo = archReadItemValue(bestAttack, "Ammo")
    if ammo == 0 then
        return { type = "Reload", item = bestAttack, index = bestAttackIdx }
    end
    return { type = "Attack", item = bestAttack, index = bestAttackIdx }
end

local function archForceSwap()
    if not archFighters then return end
    local lf = archFighters.LocalFighter
    if not lf or type(lf.Items) ~= "table" then return end
    for slotKey, item in next, lf.Items do
        if type(item) == "table" then
            local cat = archItemCategory(slotKey)
            if cat and archIsCategoryEnabled(cat) and not item.IsEquipped then
                archEquipItemByIndex(item, slotKey)
                return
            end
        end
    end
end

task.spawn(function()
    if not archFighters then return end
    local lf = archFighters.LocalFighter
    while not lf do task.wait(0.1); lf = archFighters.LocalFighter end
    archRefreshItemCache()
    pcall(function() lf:EquipItem(archGetFirstEnabledSlot()) end)
end)

