-- ▼▼▼ Step 2.3 Flickbot heartbeat engine and rage fire
local archLastFire = 0

local archRageFireThisFrame = function(targetPlayer, targetRoot, targetHead, desyncCF)
    if not archRageCfg.Active then return end
    if not (targetPlayer and targetHead and targetRoot) then return end
    if archDeflecting[targetPlayer] then return end
    local char = archPlayer.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then return end
    if not archUtil or not archEnums then return end
    local action = archGetAction()
    if not action then return end
    if action.type == "Swap" then
        archEquipItemByIndex(action.item, action.index)
        return
    end
    if action.type == "Reload" then
        archReloadItem(action.item)
        return
    end
    if tick() - archLastFire < archRageCfg.FireRate then return end
    archLastFire = tick()
    local item = action.item
    if not item then return end
    local originPos = desyncCF and desyncCF.Position or targetRoot.Position
    local aimCF     = CFrame.lookAt(originPos, targetHead.Position)
    local targetCF  = targetHead.CFrame
    local rng = Vector3.new(
        (math.random() - 0.5) * 0.1,
        (math.random() - 0.5) * 0.1,
        (math.random() - 0.5) * 0.1)
    local aimedPos  = targetHead.Position + rng
    local objOffset = targetHead.CFrame:ToObjectSpace(CFrame.new(aimedPos))
    local cameradata = {}
    cameradata[utf8.char(1)] = {
        [utf8.char(0)] = archUtil:EncodeCFrame(aimCF),
        [utf8.char(1)] = archUtil:EncodeCFrame(targetCF),
        [utf8.char(2)] = targetHead,
        [utf8.char(3)] = archUtil:EncodeCFrame(objOffset),
    }
    local remote = archRepS.Remotes.Replication.Fighter.UseItem
    pcall(function()
        remote:FireServer(
            item:Get("ObjectID"),
            archEnums:ToEnum("StartShooting"),
            cameradata,
            nil
        )
    end)
end

local archFlickbotConn = svc.RunService.Heartbeat:Connect(function()
    if not archFlickCfg.Active and not archRageCfg.Active then return end
    archUpdateDeflection()

    local flickDesyncCF = nil
    do
        local fp, fr, fh = archGetClosestTarget(archFlickCfg.TeamFilter)
        if fp and fr and fh then
            archRecordVelocity(fp.Character, fr)
            local hasKnife  = archHasKnifeViewModel(fp)
            local rawOffset = hasKnife and CFrame.new(0, 6, 0) or CFrame.new(0, 1, 2)
            if archFlickCfg.RandomizeOffset then
                archFlickCfg.OffsetX = (math.random() * 2 - 1) * 10
                archFlickCfg.OffsetY = (math.random() * 2 - 1) * 10
                archFlickCfg.OffsetZ = (math.random() * 2 - 1) * 10
            end
            local basePos = (fr.CFrame * rawOffset).Position
                + Vector3.new(
                    archFlickCfg.OffsetX,
                    archFlickCfg.OffsetY,
                    archFlickCfg.OffsetZ)
            local finalPos = basePos
            if archFlickCfg.PredictionOn and archFlickCfg.PredictionScale > 0 then
                local drift = archPredictPosition(fp.Character, fr, archFlickCfg.PredictionScale)
                    - fr.Position
                finalPos = basePos + drift
            end
            local predHead = archFlickCfg.PredictionOn
                and (fh.Position
                    + (archPredictPosition(fp.Character, fr, archFlickCfg.PredictionScale) - fr.Position))
                or fh.Position
            flickDesyncCF = CFrame.lookAt(finalPos, predHead)

            if archFlickCfg.Active then
                local myChar = archPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if myRoot then
                    if archFlickCfg.Desync then
                        local oldCF  = myRoot.CFrame
                        local oldVel = myRoot.Velocity
                        local oldRot = myRoot.RotVelocity
                        svc.RunService:UnbindFromRenderStep("__arch_flickbot_restore")
                        local applyCF = (archFlickCfg.FlickLerpAlpha >= 1.0)
                            and flickDesyncCF
                            or myRoot.CFrame:Lerp(flickDesyncCF, archFlickCfg.FlickLerpAlpha)
                        myRoot.CFrame = applyCF
                        svc.RunService:BindToRenderStep("__arch_flickbot_restore", 101, function()
                            if myRoot and myRoot.Parent then
                                myRoot.CFrame      = oldCF
                                myRoot.Velocity    = oldVel
                                myRoot.RotVelocity = oldRot
                            end
                            svc.RunService:UnbindFromRenderStep("__arch_flickbot_restore")
                        end)
                    else
                        archKillVel(myChar)
                        local n = archFlickCfg.WritesPerFrame
                        for i = 0, n - 1 do
                            local t  = tick() * archFlickCfg.FlickSpeed + (i * (math.pi * 2 / n))
                            local ox = math.cos(t) * archFlickCfg.FlickRadius
                            local oz = math.sin(t) * archFlickCfg.FlickRadius
                            myRoot.CFrame = fr.CFrame * CFrame.new(ox, 0, oz)
                        end
                    end
                end
            end
        end
    end

    if archRageCfg.Active then
        local rp, rr, rh = archGetClosestTarget(true)
        if rp and rr and rh then
            local rageCF = flickDesyncCF
            if not rageCF then
                local hasKnife  = archHasKnifeViewModel(rp)
                local rawOffset = hasKnife and CFrame.new(0, 6, 0) or CFrame.new(0, 1, 2)
                local ragePos   = (rr.CFrame * rawOffset).Position
                rageCF = CFrame.lookAt(ragePos, rh.Position)
            end
            archRageFireThisFrame(rp, rr, rh, rageCF)
        end
    end
end)

archPlayer.CharacterAdded:Connect(function()
    for k in pairs(archVelHistory) do archVelHistory[k] = nil end
    pcall(function()
        svc.RunService:UnbindFromRenderStep("__arch_flickbot_restore")
    end)
end)

