-- ▼▼▼ Step 3.2 Ragebot target selection, match checks, camera data
local function rbIsLobby()
    local playerGui = archPlayer:FindFirstChild("PlayerGui")
    local mainGui   = playerGui and playerGui:FindFirstChild("MainGui")
    local mainFrame = mainGui   and mainGui:FindFirstChild("MainFrame")
    local lobby     = mainFrame and mainFrame:FindFirstChild("Lobby")
    local currency  = lobby     and lobby:FindFirstChild("Currency")
    return currency and currency.Visible == true
end

local function rbGetDuel()
    if not rbDuelMod then
        local ps = archPlayer:FindFirstChild("PlayerScripts")
        local ct = ps and ps:FindFirstChild("Controllers")
        local dc = ct and ct:FindFirstChild("DuelController")
        if dc then
            local ok, m = pcall(require, dc)
            if ok and m then rbDuelMod = m end
        end
    end
    if rbDuelMod and rbDuelMod.GetDuel then
        local ok, duel = pcall(rbDuelMod.GetDuel, rbDuelMod, archPlayer)
        if ok then return duel end
    end
    return nil
end

local rbShootingRangeCache, rbShootingRangeChecked = false, 0
local function rbIsShootingRange()
    local now = os.clock()
    if now - rbShootingRangeChecked < 0.5 then
        return rbShootingRangeCache
    end
    rbShootingRangeChecked = now
    local function matches(value)
        if value == nil then return false end
        local text = tostring(value):lower():gsub("[%s_%-]", "")
        return text:find("shootingrange", 1, true) ~= nil
            or text:find("firingrange",   1, true) ~= nil
            or text:find("사격장",         1, true) ~= nil
    end
    for _, object in ipairs({archWs, archPlayer}) do
        for _, attribute in ipairs({"Map", "MapName", "Mode", "GameMode", "Arena", "Environment", "EnvironmentName", "ShootingRange"}) do
            local value = object:GetAttribute(attribute)
            if (value == true and attribute == "ShootingRange") or matches(value) then
                rbShootingRangeCache = true
                return true
            end
        end
    end
    local character = archPlayer.Character
    local current = character
    while current and current ~= archWs do
        if matches(current.Name) then
            rbShootingRangeCache = true
            return true
        end
        current = current.Parent
    end
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local function matchingAreaIsNear(object)
        if not matches(object.Name) or not root then return false end
        local part = object:IsA("BasePart") and object
                     or object:FindFirstChildWhichIsA("BasePart", true)
        return part and (part.Position - root.Position).Magnitude < 2000
    end
    for _, child in ipairs(archWs:GetChildren()) do
        if matchingAreaIsNear(child) then rbShootingRangeCache = true; return true end
        for _, grandchild in ipairs(child:GetChildren()) do
            if matchingAreaIsNear(grandchild) then rbShootingRangeCache = true; return true end
        end
    end
    rbShootingRangeCache = false
    return false
end

local function rbIsValidMatch()
    if rbIsLobby() or rbIsShootingRange() then return false end
    local char = archPlayer.Character
    local root = rbGetRoot(char)
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not root or not hum or hum.Health <= 0 then return false end
    local duel = rbGetDuel()
    if duel ~= nil then return true end
    return rbGetFighter() ~= nil
end

local function rbInMatchFn()
    local now = tick()
    if now - rbInMatchT < 0.25 then return rbInMatch end
    rbInMatchT = now
    rbInMatch  = rbIsValidMatch()
    return rbInMatch
end

local function rbBuildCameraData(fromPos, part)
    if not archUtil or not part then return nil end
    local look = CFrame.new(fromPos, part.Position)
    local data = {}
    data[utf8.char(1)] = {
        [utf8.char(0)] = archUtil:EncodeCFrame(look),
        [utf8.char(1)] = archUtil:EncodeCFrame(look),
        [utf8.char(2)] = part,
        [utf8.char(3)] = archUtil:EncodeCFrame(part.CFrame:ToObjectSpace(CFrame.new(part.Position))),
    }
    return data
end

local rbUpdateCamRemote = nil
local function rbGetUpdateCamRemote()
    if rbUpdateCamRemote then return rbUpdateCamRemote end
    local r = archRepS:FindFirstChild("Remotes")
    r = r and r:FindFirstChild("Replication")
    r = r and r:FindFirstChild("Fighter")
    r = r and r:FindFirstChild("UpdateCameraRotation")
    rbUpdateCamRemote = r
    return r
end

local function rbGetBestTarget()
    local root = rbGetRoot(archPlayer.Character)
    if not root then return nil end
    if archRagebotSettings.prioritizedPlayer then
        local pp = svc.Players:FindFirstChild(archRagebotSettings.prioritizedPlayer)
        if pp and not rbShouldSkip(pp) then return pp end
    end
    local best, bestV = nil, math.huge
    local useHP = archRagebotSettings.targetMode == "Lowest Health"
    for _, plr in svc.Players:GetPlayers() do
        if not rbShouldSkip(plr) then
            local char  = plr.Character
            local tr    = rbGetRoot(char)
            local hum   = char and char:FindFirstChildOfClass("Humanoid")
            local value = useHP and hum.Health or (tr.Position - root.Position).Magnitude
            if archRagebotSettings.autoPriority then
                if archRagebotSettings.priorityVoided
                    and tr.Position.Magnitude > 1000000 then
                    value -= 2000000000
                end
                if archRagebotSettings.priorityAttackers
                    and rbScanWeapon(plr) ~= "" then
                    value -= 1000000000
                end
            end
            if value < bestV then
                bestV = value
                best = plr
            end
        end
    end
    return best
end

