end
_G.__ARCH_HELPERS.rbInMatchTValue      = function(v)
    if v ~= nil then rbInMatchT = v end
    return rbInMatchT
end
_G.__ARCH_HELPERS.rbTgtTValue          = function(v)
    if v ~= nil then rbTgtT = v end
    return rbTgtT
end
_G.__ARCH_HELPERS.rbCharConn           = function(v)
    if v ~= nil then rbCharConn = v end
    return rbCharConn
end
-- ▲▲▲ Step 3.2 Ragebot target selection, match checks, camera data

-- ▼▼▼ Step 3.3 Ragebot movement engine (csync, void, orbit, noclip, offsets)
-- csync primitives
local function rbSetCsync(st, cf, pos, dt)
    local old = st.lastFakePos
    st.csyncCF     = cf
    st.csyncLV     = (old and dt and dt > 0) and (pos - old) / dt or Vector3.zero
    st.csyncAV     = Vector3.zero
    st.lastFakePos = pos
end

local function rbSetVoidCsync(st, cf, lv, av)
    st.csyncCF     = cf
    st.csyncLV     = lv or Vector3.zero
    st.csyncAV     = av or Vector3.zero
    st.lastFakePos = cf and cf.Position or nil
end

local function rbClearCsync(st)
    st.csyncCF     = nil
    st.csyncLV     = nil
    st.csyncAV     = nil
    st.lastFakePos = nil
end

local function rbVoidRand()
    local n = math.random(-2147483646, 2147483646)
    repeat n = math.random(-2147483646, 2147483646)
    until n < -1147483646 or n > 1147483646
    return n
end

local function rbVoidRandCF()
    return CFrame.new(rbVoidRand(), rbVoidRand(), rbVoidRand())
         * CFrame.Angles(math.pi, math.pi, math.pi)
end

local function rbIsSettling()
    return os.clock() < (archRagebotSettings.settleUntil or 0)
end

local function rbRestoreLocalRoot(st, root)
    if not root or not st.csyncLocalCF then return false end
    local liveV = root.AssemblyLinearVelocity
    root.CFrame = st.csyncLocalCF
    if st.csyncLocalLV then
        root.AssemblyLinearVelocity = Vector3.new(
            st.csyncLocalLV.X, liveV.Y, st.csyncLocalLV.Z)
    end
    if st.csyncLocalAV then
        root.AssemblyAngularVelocity = st.csyncLocalAV
    end
    return true
end

local function rbHasValidTarget(st)
    return st.target
        and not rbPlayerIsDead(st.target)
        and not rbIsInvincible(st.target)
end

local function rbUpdateStatus(st)
    local target  = rbHasValidTarget(st) and st.target or nil
    local voiding = not target
        or ((archRagebotSettings.mode == "Void" or archRagebotSettings.mode == "Orbit")
            and not st.voidExposed)
    setRagebotStatus(st.active and archRagebotSettings.on, target, voiding)
end

local function rbShouldShoot(st)
    if not rbHasValidTarget(st) then return false end
    if rbIsKatana(st.target) then return false end
    if archRagebotSettings.mode == "Void" and not st.voidExposed then
        return false
    end
    return true
end

-- csync loop
local function rbStartCsync(st, myGen)
    if st.csyncHbConn then return end
    st.csyncHbConn = svc.RunService.Heartbeat:Connect(function()
        local root = rbGetRoot(archPlayer.Character)
        if not root then return end
        if st.csyncWroteFake and st.csyncLocalCF then
            rbRestoreLocalRoot(st, root)
        end
        if rbIsSettling() then
            st.csyncLocalCF   = root.CFrame
            st.csyncLocalLV   = root.AssemblyLinearVelocity
            st.csyncLocalAV   = root.AssemblyAngularVelocity
            st.csyncWroteFake = false
            return
        end
        st.csyncLocalCF = root.CFrame
        st.csyncLocalLV = root.AssemblyLinearVelocity
        st.csyncLocalAV = root.AssemblyAngularVelocity
        if st.csyncCF then
            root.CFrame = st.csyncCF
            local fakeVelocity  = st.csyncLV or st.csyncLocalLV or root.AssemblyLinearVelocity
            local localVelocity = st.csyncLocalLV or root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(
                fakeVelocity.X, localVelocity.Y, fakeVelocity.Z)
            root.AssemblyAngularVelocity = st.csyncAV
                or st.csyncLocalAV
                or root.AssemblyAngularVelocity
            st.csyncWroteFake = true
        else
            st.csyncWroteFake = false
        end
    end)
    svc.RunService:BindToRenderStep(
        "RB_Csync_" .. myGen,
        Enum.RenderPriority.Camera.Value - 1,
        function()
            local root = rbGetRoot(archPlayer.Character)
            if not root or not st.csyncLocalCF then return end
            if st.csyncWroteFake and rbRestoreLocalRoot(st, root) then
                st.csyncWroteFake = false
            end
        end
    )
end

local function rbStopCsync(st, myGen)
    if st.csyncHbConn then
        st.csyncHbConn:Disconnect()
        st.csyncHbConn = nil
    end
    pcall(function()
        svc.RunService:UnbindFromRenderStep("RB_Csync_" .. myGen)
    end)
    rbRestoreLocalRoot(st, rbGetRoot(archPlayer.Character))
    rbClearCsync(st)
    st.csyncLocalCF   = nil
    st.csyncLocalLV   = nil
    st.csyncLocalAV   = nil
    st.csyncWroteFake = false
end

-- void state
local function rbEnterVoidState(st)
    st.voidTargetCF  = nil
    st.voidExposed   = false
    st.orbitClientCF = nil
    if not st.active or not archRagebotSettings.on then
        rbClearCsync(st)
        rbUpdateStatus(st)
        return
    end
    if archRagebotSettings.voidSpam then
        rbSetVoidCsync(st, rbVoidRandCF())
    else
        rbClearCsync(st)
    end
    rbUpdateStatus(st)
end

local function rbEnableVoidCsync(st, myGen)
    if st.voidHbConn then return end
    rbStartCsync(st, myGen)
    st.voidHbConn = svc.RunService.Heartbeat:Connect(function()
        if rbIsSettling() then
            st.voidTargetCF = nil
            st.voidExposed  = false
            rbClearCsync(st)
            return
        end
        local targetCF = st.voidTargetCF
        if targetCF then
            rbSetVoidCsync(st, targetCF, Vector3.zero, Vector3.zero)
        elseif archRagebotSettings.voidSpam then
            rbSetVoidCsync(st, rbVoidRandCF())
        else
            rbClearCsync(st)
        end
    end)
end

local function rbDisableVoidCsync(st, myGen)
    if st.voidHbConn then
        st.voidHbConn:Disconnect()
        st.voidHbConn = nil
    end
    pcall(function()
        svc.RunService:UnbindFromRenderStep("RB_VoidCsync_" .. myGen)
    end)
    st.voidTargetCF = nil
    st.voidThread   = nil
    st.voidExposed  = false
end

-- orbit render
local function rbStartOrbitRender(st, myGen)
    if st.orbitRenderRunning then return end
    st.orbitRenderRunning = true
    svc.RunService:BindToRenderStep(
        "RB_Orbit_" .. myGen,
        Enum.RenderPriority.First.Value,
        function()
            if not st.orbitClientCF then return end
            local root = rbGetRoot(archPlayer.Character)
            if not root then return end
            root.CFrame = st.orbitClientCF
        end
    )
end

local function rbStopOrbitRender(st, myGen)
    if not st.orbitRenderRunning then return end
    pcall(function()
        svc.RunService:UnbindFromRenderStep("RB_Orbit_" .. myGen)
    end)
    st.orbitRenderRunning = false
    st.orbitClientCF      = nil
end

-- noclip
local function rbEnableNoclip(st)
    if st.noclipConn then return end
    st.noclipConn = svc.RunService.Stepped:Connect(function()
        local char = archPlayer.Character
        if not char then return end
        for _, part in char:GetDescendants() do
            if part:IsA("BasePart") then part.CanCollide = false end
        end
    end)
end

-- offset helpers
local function rbGetDirs(targetRoot)
    local dirs  = {}
    local look  = targetRoot.CFrame.LookVector
    local right = targetRoot.CFrame.RightVector
    if archRagebotSettings.dirBack  then table.insert(dirs, -look)  end
    if archRagebotSettings.dirFront then table.insert(dirs, look)   end
    if archRagebotSettings.dirLeft  then table.insert(dirs, -right) end
    if archRagebotSettings.dirRight then table.insert(dirs, right)  end
    if #dirs == 0 then
        dirs[1] = -look
        dirs[2] = right
        dirs[3] = -right
    end
    return dirs
end

local function rbPickOffset(targetRoot, head)
    local dirs   = rbGetDirs(targetRoot)
    local dir    = dirs[math.random(1, #dirs)]
    local radius = math.clamp(archRagebotSettings.orbitDist  or 3,  1.25, 5)
    local height = math.clamp(archRagebotSettings.orbitHeight or 2, -2,   6)
    local pos    = head.Position + dir * radius + Vector3.new(0, height, 0)
    if archRagebotSettings.dirUp and math.random() < 0.2 then
        pos += Vector3.new(0, math.max(1, height), 0)
    elseif archRagebotSettings.dirDown and math.random() < 0.15 then
        pos += Vector3.new(
            0,
            -math.max(1, math.min(3, archRagebotSettings.undergroundDepth or 2)),
            0)
    end
    return pos
end

local function rbUndergroundPos(head, targetRoot)
    local depth  = math.clamp(archRagebotSettings.undergroundDepth or 6, 3, 8)
    local radius = math.clamp(archRagebotSettings.orbitDist        or 3, 1.25, 4)
    local base   = head.Position - targetRoot.CFrame.LookVector * radius
    if archRagebotSettings.undergroundBounce then
        local speed = math.max(1, archRagebotSettings.undergroundBounceSpeed or 5000)
        local phase = math.floor(os.clock() * speed) % 2
        if phase == 0 then
            return base + Vector3.new(0, -depth, 0)
        else
            local surfH = archRagebotSettings.undergroundSurfaceHeight or 0
            return base + Vector3.new(0, surfH, 0)
        end
    end
    return base + Vector3.new(0, -depth, 0)
end

_G.__ARCH_HELPERS.rbSetCsync          = rbSetCsync
_G.__ARCH_HELPERS.rbSetVoidCsync      = rbSetVoidCsync
_G.__ARCH_HELPERS.rbClearCsync        = rbClearCsync
_G.__ARCH_HELPERS.rbVoidRand          = rbVoidRand
_G.__ARCH_HELPERS.rbVoidRandCF        = rbVoidRandCF
_G.__ARCH_HELPERS.rbIsSettling        = rbIsSettling
_G.__ARCH_HELPERS.rbRestoreLocalRoot  = rbRestoreLocalRoot
_G.__ARCH_HELPERS.rbHasValidTarget    = rbHasValidTarget
_G.__ARCH_HELPERS.rbUpdateStatus      = rbUpdateStatus
_G.__ARCH_HELPERS.rbShouldShoot       = rbShouldShoot
_G.__ARCH_HELPERS.rbStartCsync        = rbStartCsync
_G.__ARCH_HELPERS.rbStopCsync         = rbStopCsync
_G.__ARCH_HELPERS.rbEnterVoidState    = rbEnterVoidState
_G.__ARCH_HELPERS.rbEnableVoidCsync   = rbEnableVoidCsync
_G.__ARCH_HELPERS.rbDisableVoidCsync  = rbDisableVoidCsync
_G.__ARCH_HELPERS.rbStartOrbitRender  = rbStartOrbitRender
_G.__ARCH_HELPERS.rbStopOrbitRender   = rbStopOrbitRender
_G.__ARCH_HELPERS.rbEnableNoclip      = rbEnableNoclip
_G.__ARCH_HELPERS.rbGetDirs           = rbGetDirs
_G.__ARCH_HELPERS.rbPickOffset        = rbPickOffset
_G.__ARCH_HELPERS.rbUndergroundPos    = rbUndergroundPos
-- ▲▲▲ Step 3.3 Ragebot movement engine (csync, void, orbit, noclip, offsets)

-- ▼▼▼ Step 3.4 Ragebot fire engine (melee, ammo, weapon profile, hook, loops)
local rbLastMeleeFire = 0

-- melee backstab
local function rbDoMeleeAttack(st, head)
    if not archUtil or not archEnums then return false end
    local fighter = rbGetFighter()
    local item    = fighter and fighter.EquippedItem
    if not item then return false end

    local now = tick()
    local attackDelay = math.max(
        (item.Info and item.Info.AttackDelay) or 0,
        archRagebotSettings.meleeMinDelay or 0,
        0.05)
    if now - rbLastMeleeFire < attackDelay then return false end

    local tc = st.target and st.target.Character
    local tr = tc and rbGetRoot(tc)
    if not tr then return false end

    local myRoot = rbGetRoot(archPlayer.Character)
    if not myRoot then return false end

    local dx  = tr.Position.X - myRoot.Position.X
    local dz  = tr.Position.Z - myRoot.Position.Z
    local mag = math.sqrt(dx * dx + dz * dz)
    if mag < 0.01 then return false end
    dx, dz = dx / mag, dz / mag

    local yaw     = math.atan2(-dx, -dz)
    local fakeYaw = yaw + math.pi

    local ok, encoded = pcall(function()
        return archUtil:EncodeCameraRotation(Vector2.new(0, fakeYaw))
    end)
    if not ok or not encoded then return false end

    local updateCam = rbGetUpdateCamRemote()
    local useRemote = archRepS.Remotes.Replication.Fighter.UseItem
    local oid       = item.Get and item:Get("ObjectID")
    local shootEnum = archEnums:ToEnum("StartShooting")
    local attempts  = math.max(1, math.floor(archRagebotSettings.shootAttempts or 1))

    rbLastMeleeFire = now

    local fired = false
    for _ = 1, attempts do
        if updateCam then
            pcall(function() updateCam:FireServer(encoded, nil) end)
        end
        if oid and shootEnum and useRemote then
            local ok2 = pcall(function()
                useRemote:FireServer(oid, shootEnum, nil, nil)
            end)
            if ok2 then fired = true end
        end
        if not fired and item.UseItem then
            pcall(function() item:UseItem() end)
            fired = true
        end
        if not fired and fighter.UseItem then
            pcall(function() fighter:UseItem() end)
            fired = true
        end
    end
    return fired
end

-- ammo handler
local function rbHandleAmmo(st)
    local fighter = rbGetFighter()
    local item    = fighter and fighter.EquippedItem
    if not fighter or not item then return false end
    local slot = item:Get("Slot") or 1
    if slot == (archRagebotSettings.meleeSlot or 3) then return false end
    local ammo = item:Get("Ammo") or 0
    local now  = tick()
    if fighter:Get("Reloading") then
        st.hideOrbitUntil = math.max(st.hideOrbitUntil or 0, now + 0.25)
        st.ammoActionAt   = math.max(st.ammoActionAt or 0, now + 0.1)
        return true
    end
    if ammo > 0 then return false end
    if now < (st.ammoActionAt or 0) then return true end
    local primary   = archRagebotSettings.primarySlot   or 1
    local secondary = archRagebotSettings.secondarySlot or 2
    if slot == primary and archRagebotSettings.autoSwapSecondary then
        st.ammoActionAt   = now + 0.45
        st.hideOrbitUntil = math.max(st.hideOrbitUntil or 0, now + 0.45)
        st.ammoFallbackSlot = secondary
        pcall(rbPressKey, rbSlotKey[secondary] or Enum.KeyCode.Two)
        return true
    end
    if slot == secondary and archRagebotSettings.autoReloadPrimary then
        st.ammoActionAt   = now + 0.8
        st.hideOrbitUntil = math.max(st.hideOrbitUntil or 0, now + 0.9)
        st.ammoFallbackSlot = primary
        pcall(rbPressKey, rbSlotKey[primary] or Enum.KeyCode.One)
        task.delay(0.18, function()
            if not st.active then return end
            local f2 = rbGetFighter()
            local i2 = f2 and f2.EquippedItem
            if f2 and i2
                and (i2:Get("Slot") or 1) == primary
                and (i2:Get("Ammo") or 0) <= 0
                and not f2:Get("Reloading") then
                pcall(rbPressKey, Enum.KeyCode.R)
            end
        end)
        return true
    end
    if slot == primary and archRagebotSettings.autoReloadPrimary then
        st.ammoActionAt   = now + 0.8
        st.hideOrbitUntil = math.max(st.hideOrbitUntil or 0, now + 0.9)
        pcall(rbPressKey, Enum.KeyCode.R)
        return true
    end
    return true
end

local function rbEquipSlot(slot)
    slot = tonumber(slot) or 1
    pcall(rbPressKey, rbSlotKey[slot] or Enum.KeyCode.One)
end

local function rbApplyWeaponProfile(st)
    if archRagebotSettings.weaponSpecialize == false then return "default" end
    local fighter = rbGetFighter()
    local item    = fighter and fighter.EquippedItem
    local slot    = item and item:Get("Slot") or nil
    local pref    = archRagebotSettings.preferredWeapon or "primary"
    if archRagebotSettings.autoEquipPreferred ~= false and not st.preferredEquipped then
        local want =
            (pref == "secondary" and (archRagebotSettings.secondarySlot or 2))
            or (pref == "melee" and (archRagebotSettings.meleeSlot or 3))
            or (archRagebotSettings.primarySlot or 1)
        if slot ~= want then
            rbEquipSlot(want)
            slot = want
        end
        st.preferredEquipped = true
    end
    local kind
    if slot == (archRagebotSettings.meleeSlot or 3) or pref == "melee" then
        kind = "melee"
    elseif slot == (archRagebotSettings.secondarySlot or 2) or pref == "secondary" then
        kind = "secondary"
    else
        kind = "primary"
    end
    if kind == "primary" then
        archRagebotSettings.hyper          = true
        archRagebotSettings.orbitDist      = 3.2
        archRagebotSettings.orbitHeight    = 2.2
        archRagebotSettings.strafeSpeed    = 5000000
        archRagebotSettings.teleportDelay  = 0
        archRagebotSettings.behindDist     = 3.5
        archRagebotSettings.randomMovement = false
        archRagebotSettings.dirBack        = true
        archRagebotSettings.dirFront       = false
        archRagebotSettings.dirLeft        = true
        archRagebotSettings.dirRight       = true
    elseif kind == "secondary" then
        archRagebotSettings.hyper          = false
        archRagebotSettings.orbitDist      = 2.6
        archRagebotSettings.orbitHeight    = 1.6
        archRagebotSettings.strafeSpeed    = 4000000
        archRagebotSettings.teleportDelay  = 0
        archRagebotSettings.behindDist     = 3.0
        archRagebotSettings.randomMovement = true
        archRagebotSettings.randomRefresh  = 0.07
        archRagebotSettings.dirBack        = true
        archRagebotSettings.dirFront       = true
        archRagebotSettings.dirLeft        = true
        archRagebotSettings.dirRight       = true
    else
        archRagebotSettings.hyper              = true
        archRagebotSettings.orbitDist          = 0.1
        archRagebotSettings.orbitHeight        = -0.5
        archRagebotSettings.strafeSpeed        = 999999
        archRagebotSettings.teleportDelay      = 0.0
        archRagebotSettings.behindDist         = 0.5
        archRagebotSettings.undergroundDepth   = 8
        archRagebotSettings.randomMovement     = false
        archRagebotSettings.dirBack            = true
        archRagebotSettings.dirFront           = false
        archRagebotSettings.dirLeft            = false
        archRagebotSettings.dirRight           = false
        archRagebotSettings.dirDown            = true
        archRagebotSettings.undergroundBounce       = true
        archRagebotSettings.undergroundBounceSpeed  = 999999
    end
    st.weaponKind = kind
    return kind
end

-- fire
local function rbDoFire(st, part)
    if st.weaponKind == "melee" then
        return rbDoMeleeAttack(st, part)
    end
    local fighter = rbGetFighter()
    local item    = fighter and fighter.EquippedItem
    if not item or not part then return false end
    local cam     = archWs.CurrentCamera
    local fromPos = (st.csyncCF and st.csyncCF.Position)
        or (cam and cam.CFrame.Position)
        or part.Position
    local anyFired = false
    local attempts = math.max(1, math.floor(archRagebotSettings.shootAttempts or 1))
    local useItemRemote = archRepS.Remotes.Replication.Fighter.UseItem
    for _ = 1, attempts do
        local fired = false
        if archRagebotSettings.useManipulation and useItemRemote and archEnums and archUtil then
            local ammo = item.Get and (item:Get("Ammo") or 0) or 0
            if ammo > 0 then
                local oid       = item:Get("ObjectID")
                local shootEnum = archEnums:ToEnum("StartShooting")
                local data      = rbBuildCameraData(fromPos, part)
                if oid and shootEnum and data then
                    fired = pcall(function()
                        useItemRemote:FireServer(oid, shootEnum, data, nil)
                    end)
                end
            end
        end
        if not fired and item.UseItem then
            fired = pcall(function() item:UseItem() end)
        end
        if not fired and fighter and fighter.UseItem then
            fired = pcall(function() fighter:UseItem() end)
        end
        anyFired = anyFired or fired
    end
    return anyFired
end

-- UseItem hook (Void mode path)
local rbHookInstalled = false
local rbOldFireServer = nil

local function rbInstallHook(st)
    if rbHookInstalled then return end
    local useItemRemote = archRepS.Remotes.Replication.Fighter.UseItem
    if not useItemRemote then return end
    if not hookfunction then return end
    rbHookInstalled = true
    rbOldFireServer = hookfunction(
        useItemRemote.FireServer,
        newcclosure(function(self, oid, action, cameradata, ...)
            if st.active
                and archRagebotSettings.on
                and archRagebotSettings.mode == "Void"
                and archRagebotSettings.useManipulation
                and archEnums
                and action == archEnums:ToEnum("StartShooting") then
                if rbIsLobby() or not rbInMatchFn() then
                    return rbOldFireServer(self, oid, action, cameradata, ...)
                end
                local target = st.target
                if rbHasValidTarget(st) and not rbIsKatana(target) then
                    local tc   = target.Character
                    local tr   = rbGetRoot(tc)
                    local head = tc and (tc:FindFirstChild("Head") or tr)
                    if tr and head then
                        local shootPos = rbIsRiotShield(target)
                            and (tr.Position - tr.CFrame.LookVector * (archRagebotSettings.behindDist or 4))
                            or  (tr.Position - tr.CFrame.LookVector * 2.5 + Vector3.new(0, 1.5, 0))
                        if not rbIsSafePos(shootPos, target) then
                            rbEnterVoidState(st)
                            return rbOldFireServer(self, oid, action, cameradata, ...)
                        end
                        local shootCF = CFrame.new(shootPos, head.Position)
                        st.voidExposed  = true
                        st.voidTargetCF = shootCF
                        rbSetVoidCsync(st, shootCF, Vector3.zero, Vector3.zero)
                        rbUpdateStatus(st)
                        task.wait(0.02)
                        local newData = rbBuildCameraData(shootPos, head) or cameradata
                        task.spawn(function()
                            task.wait(0.05)
                            rbEnterVoidState(st)
                        end)
                        return rbOldFireServer(self, oid, action, newData, ...)
                    end
                end
            end
            return rbOldFireServer(self, oid, action, cameradata, ...)
        end)
    )
end

-- void loop
local function rbStartVoidLoop(st, myGen)
    if st.voidThread then return end
    rbEnableVoidCsync(st, myGen)
    local thread
    thread = task.spawn(function()
        while st.active
            and archRagebotSettings.on
            and rbGen == myGen
            and not st.suspended do
            if rbIsSettling() then
                st.voidTargetCF = nil
                st.voidExposed  = false
                rbClearCsync(st)
                task.wait(0.03)
                continue
            end
            if not rbInMatchFn() or not rbHasValidTarget(st) or rbIsKatana(st.target) then
                rbEnterVoidState(st)
                task.wait(0.1)
                continue
            end
            rbEnterVoidState(st)
            if archRagebotSettings.voidHideTime > 0 then
                task.wait(archRagebotSettings.voidHideTime)
            end
            if not st.active or not archRagebotSettings.on
                or rbGen ~= myGen or st.suspended or not rbInMatchFn() then
                break
            end
            local target = st.target
            if rbHasValidTarget(st) and not rbIsKatana(target) then
                local tc   = target.Character
                local tr   = rbGetRoot(tc)
                local head = tc and (tc:FindFirstChild("Head") or tr)
                if tr and head then
                    local shootPos = rbIsRiotShield(target)
                        and (tr.Position - tr.CFrame.LookVector * (archRagebotSettings.behindDist or 4))
                        or  (tr.Position - tr.CFrame.LookVector * 2.5 + Vector3.new(0, 1.5, 0))
                    if not rbIsSafePos(shootPos, target) then
                        rbEnterVoidState(st)
                        task.wait(0.1)
                        continue
                    end
                    local shootCF = CFrame.new(shootPos, head.Position)
                    st.voidExposed  = true
                    st.voidTargetCF = shootCF
                    rbSetVoidCsync(st, shootCF, Vector3.zero, Vector3.zero)
                    rbUpdateStatus(st)
                    if archRagebotSettings.voidShootTime > 0 then
                        task.wait(archRagebotSettings.voidShootTime)
                    end
                    if rbHasValidTarget(st) and not rbIsKatana(target) then
                        rbDoFire(st, head)
                    end
                    task.wait(0.05)
                    rbEnterVoidState(st)
                end
            end
        end
        if st.voidThread == thread then st.voidThread = nil end
        if rbGen == myGen and not st.suspended and st.voidThread == nil then
            rbDisableVoidCsync(st, myGen)
        end
    end)
    st.voidThread = thread
end

-- ammo loop
local function rbStartAmmoLoop(st)
    if st.ammoThread then return end
    st.ammoThread = task.spawn(function()
        while st.active do
            if rbIsShootingRange() then
                task.wait(0.1)
                continue
            end
            if not rbHandleAmmo(st)
                and rbShouldShoot(st)
                and not archRagebotSettings.hyper then
                local tc   = st.target and st.target.Character
                local head = tc and (tc:FindFirstChild("Head") or rbGetRoot(tc))
                if head then
                    if archRagebotSettings.shootDelay > 0 then
                        task.wait(archRagebotSettings.shootDelay)
                    end
                    rbDoFire(st, head)
                end
            end
            task.wait(archRagebotSettings.acSpd)
        end
        st.ammoThread = nil
    end)
end

_G.__ARCH_HELPERS.rbDoMeleeAttack     = rbDoMeleeAttack
_G.__ARCH_HELPERS.rbHandleAmmo        = rbHandleAmmo
_G.__ARCH_HELPERS.rbEquipSlot         = rbEquipSlot
_G.__ARCH_HELPERS.rbApplyWeaponProfile = rbApplyWeaponProfile
_G.__ARCH_HELPERS.rbDoFire            = rbDoFire
_G.__ARCH_HELPERS.rbInstallHook       = rbInstallHook
_G.__ARCH_HELPERS.rbStartVoidLoop     = rbStartVoidLoop
_G.__ARCH_HELPERS.rbStartAmmoLoop     = rbStartAmmoLoop
_G.__ARCH_HELPERS.rbLastMeleeFire     = function(v)
    if v ~= nil then rbLastMeleeFire = v end
    return rbLastMeleeFire
end
-- ▲▲▲ Step 3.4 Ragebot fire engine (melee, ammo, weapon profile, hook, loops)

-- ▼▼▼ Step 3.5 Ragebot start / stop main loop
local function stopRagebot()
    rbGen += 1
    if rbActiveState then
        local st = rbActiveState
        st.active          = false
        archRagebotSettings.on = false
        setRagebotStatus(false)
        if st.conn       then st.conn:Disconnect();       st.conn       = nil end
        if st.noclipConn then st.noclipConn:Disconnect(); st.noclipConn = nil end
        st.target             = nil
        st.voidExposed        = false
        st.nextTeleportAt     = 0
        st.ammoActionAt       = 0
        st.hideOrbitUntil     = 0
        st.randPos            = nil
        st.randT              = 0
        st.lastFakePos        = nil
        rbInMatchT            = 0
        rbInMatch             = false
        rbStopCsync(st, rbGen - 1)
        rbDisableVoidCsync(st, rbGen - 1)
        rbStopOrbitRender(st, rbGen - 1)
        local char = archPlayer.Character
        if char then
            for _, part in char:GetDescendants() do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
        end
        rbActiveState = nil
    end
    if rbCharConn then rbCharConn:Disconnect(); rbCharConn = nil end
end

local function startRagebot()
    if rbActiveState then stopRagebot() end
    archRagebotSettings.on = true
    archRagebotSettings.settleUntil = 0
    rbGen += 1
    local myGen = rbGen

    local st = {
        active            = true,
        target            = nil,
        conn              = nil,
        ammoThread        = nil,
        voidThread        = nil,
        voidHbConn        = nil,
        csyncHbConn       = nil,
        voidExposed       = false,
        voidTargetCF      = nil,
        nextTeleportAt    = 0,
        ammoActionAt      = 0,
        ammoFallbackSlot  = nil,
        hideOrbitUntil    = 0,
        preferredEquipped = false,
        randPos           = nil,
        randT             = 0,
        lastFakePos       = nil,
        csyncCF           = nil,
        csyncLV           = nil,
        csyncAV           = nil,
        csyncLocalCF      = nil,
        csyncLocalLV      = nil,
        csyncLocalAV      = nil,
        csyncWroteFake    = false,
        noclipConn        = nil,
        suspended         = rbIsShootingRange(),
        weaponKind        = nil,
        orbitRenderRunning = false,
        orbitClientCF     = nil,
    }
    rbActiveState = st

    setRagebotStatus(true, nil, true)
    rbStartAmmoLoop(st)
    rbInstallHook(st)

    if not st.suspended then
        rbEnableNoclip(st)
        local mode = archRagebotSettings.mode
        if mode == "Void" then
            rbStartVoidLoop(st, myGen)
        elseif mode == "Orbit" then
            rbEnableVoidCsync(st, myGen)
            rbStartOrbitRender(st, myGen)
        else
            rbStartCsync(st, myGen)
        end
    end

    local aaPhase    = 0
    local orbitAngle = math.random() * math.pi * 2
    local function rnd()    return math.random() * 2 - 1 end
    local function rndDir()
        local angle = math.random() * math.pi * 2
        return Vector3.new(math.cos(angle), 0, math.sin(angle))
    end

    st.conn = svc.RunService.Stepped:Connect(function(_, dt)
        if not st.active or not archRagebotSettings.on then
            if st.conn then st.conn:Disconnect(); st.conn = nil end
            return
        end

        if rbIsShootingRange() then
            if not st.suspended then
                st.suspended    = true
                st.target       = nil
                st.randPos      = nil
                st.voidTargetCF = nil
                st.voidExposed  = false
                if st.noclipConn then
                    st.noclipConn:Disconnect()
                    st.noclipConn = nil
                end
                rbStopCsync(st, myGen)
                rbDisableVoidCsync(st, myGen)
                rbStopOrbitRender(st, myGen)
                rbUpdateStatus(st)
            end
            return
        end

        if st.suspended then
            st.suspended = false
            rbEnableNoclip(st)
            local mode = archRagebotSettings.mode
            if mode == "Void" then
                rbStartVoidLoop(st, myGen)
            elseif mode == "Orbit" then
                rbEnableVoidCsync(st, myGen)
                rbStartOrbitRender(st, myGen)
            else
                rbStartCsync(st, myGen)
            end
        end

        local root = rbGetRoot(archPlayer.Character)
        if not root then return end

        if rbIsSettling() then
            st.voidTargetCF  = nil
            st.voidExposed   = false
            st.orbitClientCF = nil
            rbClearCsync(st)
            rbUpdateStatus(st)
            return
        end

        if not rbInMatchFn() then
            rbClearCsync(st)
            st.target = nil
            if archRagebotSettings.mode == "Orbit" then
                rbEnterVoidState(st)
            else
                rbUpdateStatus(st)
            end
            return
        end

        local now = tick()

        if st.target and rbPlayerIsDead(st.target) then st.target = nil end
        if st.target and rbIsInvincible(st.target) then
            rbClearCsync(st)
            if archRagebotSettings.mode == "Orbit" then
                rbEnterVoidState(st)
            else
                rbUpdateStatus(st)
            end
            return
        end

        if now - rbTgtT >= 0.0005
            and (archRagebotSettings.autoSwitch or not st.target) then
            rbTgtT = now
            if archRagebotSettings.autoSwitch then
                local target = rbGetBestTarget()
                if target then
                    if archRagebotSettings.sendNotification
                        and st.target ~= target then
                        task.spawn(function()
                            context.ui.notify("ragebot -> " .. target.Name)
                        end)
                    end
                    st.target = target
                end
            elseif not st.target then
                st.target = rbGetBestTarget()
            end
        end

        if not st.target then
            rbClearCsync(st)
            if archRagebotSettings.mode == "Orbit" then
                rbEnterVoidState(st)
            else
                rbUpdateStatus(st)
            end
            return
        end

        local tc   = st.target.Character
        local tr   = rbGetRoot(tc)
        local head = tc and (tc:FindFirstChild("Head") or tr)
        if not tc or not tr or not head then
            st.target = nil
            rbUpdateStatus(st)
            return
        end

        if rbIsNearOtherMatch(tr.Position, st.target) then
            st.target  = nil
            st.randPos = nil
            if archRagebotSettings.mode == "Orbit"
                or archRagebotSettings.mode == "Void" then
                rbEnterVoidState(st)
            else
                rbClearCsync(st)
                rbUpdateStatus(st)
            end
            return
        end

        rbUpdateStatus(st)
        rbApplyWeaponProfile(st)

        if archRagebotSettings.mode == "Void" then return end

        if archRagebotSettings.mode == "Orbit"
            and (now < (st.hideOrbitUntil or 0) or rbHandleAmmo(st)) then
            st.voidTargetCF  = nil
            st.voidExposed   = false
            st.orbitClientCF = nil
            rbEnterVoidState(st)
            return
        end

        local isUnderground = archRagebotSettings.mode == "Underground"
            or archRagebotSettings.undergroundOverride == true
        local isShield      = rbIsRiotShield(st.target)
        local height        = math.clamp(archRagebotSettings.orbitHeight or 2, -2, 6)
        local radius        = math.clamp(archRagebotSettings.orbitDist   or 3, 1.25, 5)
        local targetPos

        if isShield then
            targetPos = tr.Position - tr.CFrame.LookVector * (archRagebotSettings.behindDist or 3)
        elseif isUnderground then
            targetPos = rbUndergroundPos(head, tr)
        elseif archRagebotSettings.mode == "Teleport" then
            if archRagebotSettings.randomMovement then
                if not st.randPos
                    or (now - (st.randT or 0)) >= (archRagebotSettings.randomRefresh or 0.08) then
                    st.randT   = now
                    st.randPos = rbPickOffset(tr, head)
                        + rndDir() * (math.random() * 1.05)
                        + Vector3.new(0, rnd() * 0.7, 0)
                end
                targetPos = st.randPos
            else
                targetPos = rbPickOffset(tr, head)
            end
        elseif archRagebotSettings.mode == "Orbit" then
            orbitAngle += dt * math.max(
                1,
                (archRagebotSettings.strafeSpeed or 5) * 1500)
            targetPos = head.Position
                + Vector3.new(
                    math.cos(orbitAngle) * radius,
                    height,
                    math.sin(orbitAngle) * radius)
        else
            targetPos = rbUndergroundPos(head, tr)
        end

        if not rbIsSafePos(targetPos, st.target) then
            st.randPos = nil
            if archRagebotSettings.mode == "Orbit" and not isUnderground then
                st.voidTargetCF  = nil
                st.voidExposed   = false
                st.orbitClientCF = nil
                rbEnterVoidState(st)
            else
                rbClearCsync(st)
                rbUpdateStatus(st)
            end
            return
        end

        local faceCF = CFrame.new(targetPos, head.Position)
        if archRagebotSettings.antiAim then
            aaPhase += dt * 20
            faceCF   = CFrame.new(targetPos, head.Position)
                * CFrame.Angles(0, math.rad(math.sin(aaPhase) * 70), 0)
        end

        if archRagebotSettings.mode == "Orbit" and not isUnderground then
            if archRagebotSettings.hyper then
                st.voidExposed   = true
                st.voidTargetCF  = faceCF
                st.orbitClientCF = faceCF
                rbSetCsync(st, faceCF, targetPos, dt)
                rbUpdateStatus(st)
                if rbShouldShoot(st) then rbDoFire(st, head) end
            end
        else
            rbSetCsync(st, faceCF, targetPos, dt)
            if archRagebotSettings.hyper then
                if rbShouldShoot(st) then rbDoFire(st, head) end
            elseif archRagebotSettings.mode == "Teleport" and not isUnderground then
                if now >= (st.nextTeleportAt or 0) then
                    st.nextTeleportAt = now
                        + math.max(0.01, archRagebotSettings.teleportDelay or 0.04)
                    if rbShouldShoot(st) then rbDoFire(st, head) end
                end
            elseif isUnderground then
                if rbShouldShoot(st) then rbDoFire(st, head) end
            end
        end
    end)

    rbCharConn = archPlayer.CharacterAdded:Connect(function()
        rbStopCsync(st, myGen)
        rbDisableVoidCsync(st, myGen)
        rbStopOrbitRender(st, myGen)
        st.target         = nil
        rbClearCsync(st)
        st.csyncLocalCF   = nil
        st.csyncLocalLV   = nil
        st.csyncLocalAV   = nil
        st.csyncWroteFake = false
        st.voidExposed    = false
        st.hideOrbitUntil = 0
        rbLastMeleeFire   = 0
        if st.active then
            task.wait(0.5)
            if st.active then
                local mode = archRagebotSettings.mode
                if mode == "Void" then
                    rbStartVoidLoop(st, myGen)
                elseif mode == "Orbit" then
                    rbEnableVoidCsync(st, myGen)
                    rbStartOrbitRender(st, myGen)
                else
                    rbStartCsync(st, myGen)
                end
            end
        end
    end)
end

_G.__ARCH_HELPERS.startRagebot = startRagebot
_G.__ARCH_HELPERS.stopRagebot  = stopRagebot
_G.__ARCH_HELPERS.rbGenAccessor = function(v)
    if v ~= nil then rbGen = v end
    return rbGen
end
