    text    = 'force target',
    values  = archPlayerNames(),
    default = '(none)',
    tooltip = 'always target this player first',
})
forceTargetDropdown:onChanged(function(v)
    archRagebotSettings.prioritizedPlayer = (v == '(none)') and nil or v
    archMarkRagebotSettingsDirty()
end)

local function refreshForceTargetList()
    local names = archPlayerNames()
    if forceTargetDropdown and forceTargetDropdown.setValues then
        forceTargetDropdown:setValues(names)
    end
end

