local hvhSlots = { Primary = 1, Secondary = 2, Melee = 3, Knife = 3 }
local function hvhGetSlotNumber()
    return hvhSlots[getgenv().HvhCfg.WeaponSlot] or 3
end

task.spawn(function()
    if not archFighters then return end
    local lf = archFighters.LocalFighter
    while not lf do
        task.wait(0.1)
        lf = archFighters.LocalFighter
    end
    pcall(function() lf:EquipItem(hvhGetSlotNumber()) end)
end)

task.spawn(function()
    while true do
        task.wait(1)
        if not getgenv().HvhCfg.Enabled then continue end
        local lf = archFighters and archFighters.LocalFighter
        if lf then
            pcall(function() lf:EquipItem(hvhGetSlotNumber()) end)
        end
    end
end)

local hvhLastFire     = 0
local hvhKnifeAiming  = false
local hvhKnifeLoopID  = 0
local hvhKnifeFireLast = 0

local function hvhKnifeCalcYaw(targetRoot)
    local char = archPlayer.Character
    local myRoot = char and char:FindFirstChild("HumanoidRootPart")
    if not myRoot or not targetRoot then return 0 end
    local dx = targetRoot.Position.X - myRoot.Position.X
    local dz = targetRoot.Position.Z - myRoot.Position.Z
    local mag = math.sqrt(dx * dx + dz * dz)
    if mag < 0.01 then return 0 end
    return math.atan2(-(dx / mag), -(dz / mag))
end

local function hvhKnifeStopLoop()
    hvhKnifeLoopID += 1
    hvhKnifeAiming  = false
end

local function hvhKnifeStartLoop()
    hvhKnifeLoopID += 1
    local myID = hvhKnifeLoopID

    task.spawn(function()
        while hvhKnifeAiming
            and hvhKnifeLoopID == myID
            and getgenv().HvhCfg.Enabled
            and getgenv().HvhCfg.WeaponSlot == "beat ue" do

            local _, targetRoot, targetHead = archGetClosestTarget(true)

            if targetRoot and targetHead and archUtil and archEnums then
                local char = archPlayer.Character
                local myRoot = char and char:FindFirstChild("HumanoidRootPart")

                if myRoot then
                    local behindPos = targetRoot.Position
                                    + targetRoot.CFrame.LookVector * 1.5
                                    - Vector3.new(0, 2.0, 0)
                    local snapCF = CFrame.new(behindPos, targetHead.Position)

                    local oldCF  = myRoot.CFrame
                    local oldVel = myRoot.Velocity
                    local oldRot = myRoot.RotVelocity
                    myRoot.CFrame = snapCF
                    svc.RunService:BindToRenderStep("__arch_hvh_knife_restore", 101, function()
                        if myRoot and myRoot.Parent then
                            myRoot.CFrame      = oldCF
                            myRoot.Velocity    = oldVel
                            myRoot.RotVelocity = oldRot
                        end
                        svc.RunService:UnbindFromRenderStep("__arch_hvh_knife_restore")
                    end)

                    local fakeYaw = hvhKnifeCalcYaw(targetRoot) + math.pi
                    local ok, encoded = pcall(function()
                        return archUtil:EncodeCameraRotation(Vector2.new(0, fakeYaw))
                    end)
                    if ok and encoded then
                        local ucr = rbGetUpdateCamRemote()
                        if ucr then
                            pcall(function() ucr:FireServer(encoded, nil) end)
                        end
                    end

                    local now  = tick()
                    local lf   = archFighters and archFighters.LocalFighter
                    local item = lf and lf.EquippedItem
                    if item then
                        local floor = math.max(
                            (item.Info and item.Info.AttackDelay) or 0,
                            0.05)
                        if now - hvhKnifeFireLast >= floor then
                            hvhKnifeFireLast = now
                            local oid       = item.Get and item:Get("ObjectID")
                            local shootEnum = archEnums:ToEnum("StartShooting")
                            local useRemote = archRepS.Remotes.Replication.Fighter.UseItem
                            if oid and shootEnum and useRemote then
                                pcall(function()
                                    useRemote:FireServer(oid, shootEnum, nil, nil)
                                end)
                            end
                        end
                    end
                end
            end

            task.wait()
        end

        pcall(function()
            svc.RunService:UnbindFromRenderStep("__arch_hvh_knife_restore")
        end)
    end)
end

svc.UserInputService.InputBegan:Connect(function(input, gpe)
    if gpe then return end
    if input.UserInputType ~= Enum.UserInputType.MouseButton2 then return end
    if not getgenv().HvhCfg.Enabled then return end
    if getgenv().HvhCfg.WeaponSlot ~= "beat ue" then return end
    if not hvhKnifeAiming then
        hvhKnifeAiming = true
        hvhKnifeStartLoop()
    end
end)

svc.UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton2
       and hvhKnifeAiming
       and not (getgenv().HvhCfg.Enabled and getgenv().HvhCfg.WeaponSlot == "beat ue") then
        hvhKnifeStopLoop()
    end
end)

task.spawn(function()
    while true do
        task.wait(0.1)
        local cfg = getgenv().HvhCfg
        if cfg.Enabled and cfg.WeaponSlot == "beat ue" then
            if not hvhKnifeAiming then
                hvhKnifeAiming = true
                hvhKnifeStartLoop()
            end
        else
            if hvhKnifeAiming then
                hvhKnifeStopLoop()
            end
        end
    end
end)

do
    local KnifeItem = nil
    pcall(function()
        local ps = archPlayer:FindFirstChild("PlayerScripts")
        local ms = ps and ps:FindFirstChild("Modules")
        local it = ms and ms:FindFirstChild("Items")
        local kn = it and it:FindFirstChild("Knife")
        if kn then
            local ok, m = pcall(require, kn)
            if ok then KnifeItem = m end
        end
    end)
    if KnifeItem and KnifeItem.StartAiming then
        local _origStartAiming = KnifeItem.StartAiming
        KnifeItem.StartAiming = function(self, ...)
            local fighter = self and self.ClientFighter
            local isLocal = fighter
                and (fighter.IsLocalPlayer == true or fighter.Player == archPlayer)
            if isLocal
               and getgenv().HvhCfg.Enabled
               and getgenv().HvhCfg.WeaponSlot == "beat ue" then
                hvhKnifeAiming = true
                hvhKnifeStartLoop()
                local dur = math.max(
                    (self.Info and self.Info.AttackDelay) or 0.35,
                    0.35)
                task.delay(dur, hvhKnifeStopLoop)
            end
            return _origStartAiming(self, ...)
        end
    end
end

local hvhHbConn
hvhHbConn = svc.RunService.Stepped:Connect(function()
    local cfg = getgenv().HvhCfg
    if not cfg.Enabled then return end
    if cfg.WeaponSlot == "beat ue" then return end
    if not archUtil or not archEnums then return end

    local targetPlayer, targetRoot, targetHead = archGetClosestTarget(true)
    if not (targetPlayer and targetRoot and targetHead) then return end
    if archDeflecting[targetPlayer] then return end

    local char = archPlayer.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then return end
    local myRoot = char:FindFirstChild("HumanoidRootPart")

    local desyncPos
    if archHasKnifeViewModel(targetPlayer) then
        desyncPos = (targetRoot.CFrame * CFrame.new(0, 6, 0)).Position
    else
        desyncPos = (targetRoot.CFrame * CFrame.new(0, 1, 2)).Position
    end
    local desyncCF = CFrame.lookAt(desyncPos, targetHead.Position)

    local oldCF  = myRoot.CFrame
    local oldVel = myRoot.Velocity
    local oldRot = myRoot.RotVelocity

    local reps = math.max(1, math.floor(cfg.FollowSpeed or 1000))
    for _ = 1, reps do
        myRoot.CFrame = desyncCF
    end

    svc.RunService:BindToRenderStep("__arch_hvh_restore", 101, function()
        if myRoot and myRoot.Parent then
            myRoot.CFrame      = oldCF
            myRoot.Velocity    = oldVel
            myRoot.RotVelocity = oldRot
        end
        svc.RunService:UnbindFromRenderStep("__arch_hvh_restore")
    end)

    if tick() - hvhLastFire < cfg.FireRate then return end
    hvhLastFire = tick()

    local lf = archFighters and archFighters.LocalFighter
    if not lf then return end
    local item = lf.EquippedItem
    if not item then return end

    local rng = Vector3.new(
        (math.random() - 0.5) * 0.1,
        (math.random() - 0.5) * 0.1,
        (math.random() - 0.5) * 0.1)
    local aimedPos  = targetHead.Position + rng
    local aimCF     = CFrame.lookAt(desyncCF.Position, aimedPos)
    local targetCF  = targetHead.CFrame
    local objOffset = targetHead.CFrame:ToObjectSpace(CFrame.new(aimedPos))

    local cameradata = {}
    cameradata[utf8.char(1)] = {
        [utf8.char(0)] = archUtil:EncodeCFrame(aimCF),
        [utf8.char(1)] = archUtil:EncodeCFrame(targetCF),
        [utf8.char(2)] = targetHead,
        [utf8.char(3)] = archUtil:EncodeCFrame(objOffset),
    }

    pcall(function()
        archRepS.Remotes.Replication.Fighter.UseItem:FireServer(
            item:Get("ObjectID"),
            archEnums:ToEnum("StartShooting"),
            cameradata,
            nil
        )
    end)
end)

archPlayer.CharacterAdded:Connect(function()
    pcall(function()
        svc.RunService:UnbindFromRenderStep("__arch_hvh_restore")
        svc.RunService:UnbindFromRenderStep("__arch_hvh_knife_restore")
    end)
end)

