-- ▼▼▼ Step 5.1 Auto-Shoot engine
local asTargetCache   = {}
local asLastCacheTime = 0
local AS_CACHE_TTL    = 0.35

local function asRebuildCache()
    asTargetCache = {}
    local char = archPlayer.Character
    for _, obj in ipairs(archWs:GetDescendants()) do
        if obj:IsA("Model") and obj ~= char then
            local pRoot  = obj:FindFirstChild("HumanoidRootPart")
            local pHead  = obj:FindFirstChild("Head")
            local pTorso = obj:FindFirstChild("UpperTorso") or obj:FindFirstChild("Torso")
            local pHum   = obj:FindFirstChildWhichIsA("Humanoid")
            if pRoot and pHead and pHum then
                local plrObj = svc.Players:GetPlayerFromCharacter(obj)
                table.insert(asTargetCache, {
                    Model    = obj,
                    Root     = pRoot,
                    Head     = pHead,
                    Torso    = pTorso,
                    Hum      = pHum,
                    IsPlayer = plrObj ~= nil,
                    Player   = plrObj,
                })
            end
        end
    end
end

local asSlots = { Primary = 1, Secondary = 2, Melee = 3 }
local function asGetSlotNumber()
    return asSlots[getgenv().ASCfg.WeaponSlot] or 1
end

local function asInFOV(worldPos)
    local vp, onScreen = archWs.CurrentCamera:WorldToViewportPoint(worldPos)
    if not onScreen or vp.Z < 0 then return false end
    local center = archWs.CurrentCamera.ViewportSize / 2
    return (Vector2.new(vp.X, vp.Y) - center).Magnitude <= getgenv().ASCfg.FOVRadius
end

local function asIsVisible(from, to, targetModel)
    local rp = RaycastParams.new()
    rp.FilterDescendantsInstances = { archPlayer.Character }
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local result = archWs:Raycast(from, (to - from) * 0.99, rp)
    if result == nil then return true end
    return result.Instance:IsDescendantOf(targetModel)
end

local function asResolveHitPart(entry)
    local hp = getgenv().ASCfg.HitPart
    if hp == "Head"  then return entry.Head end
    if hp == "Torso" then return entry.Torso or entry.Head end
    local pool = {}
    for _, name in ipairs({
        "Head", "UpperTorso", "Torso", "LowerTorso",
        "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg",
    }) do
        local p = entry.Model:FindFirstChild(name)
        if p then table.insert(pool, p) end
    end
    return pool[math.random(1, #pool)] or entry.Head
end

local function asPredictedPos(entry, part)
    if not getgenv().ASCfg.PredictEnabled then return part.Position end
    local vel = entry.Root.AssemblyLinearVelocity
    return part.Position + vel * getgenv().ASCfg.PredictTime
end

local asLockedEntry = nil

local function asValidateLock()
    if not asLockedEntry then return false end
    local hum  = asLockedEntry.Hum
    local root = asLockedEntry.Root
    if not hum or not hum.Parent or hum.Health <= 0 then
        asLockedEntry = nil
        return false
    end
    local char   = archPlayer.Character
    local myRoot = char and char:FindFirstChild("HumanoidRootPart")
    if not myRoot then
        asLockedEntry = nil
        return false
    end
    if (myRoot.Position - root.Position).Magnitude > getgenv().ASCfg.MaxDistance then
        asLockedEntry = nil
        return false
    end
    return true
end

local function asGetBestTarget()
    local cfg = getgenv().ASCfg
    if cfg.TargetLock and asValidateLock() then return asLockedEntry end
    asLockedEntry = nil
    local char   = archPlayer.Character
    local myRoot = char and char:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil end
    local now = os.clock()
    if now - asLastCacheTime > AS_CACHE_TTL then
        asRebuildCache()
        asLastCacheTime = now
    end
    local best, bestScore = nil, math.huge
    local center = archWs.CurrentCamera.ViewportSize / 2
    for _, entry in ipairs(asTargetCache) do
        local hum = entry.Hum
        if not hum or not hum.Parent or hum.Health <= 0 then
            continue
        end
        if entry.IsPlayer then
            if not cfg.TargetPlayers then continue end
            if cfg.TeamCheck and entry.Player and entry.Player.Team == archPlayer.Team then
                continue
            end
        end
        local dist = (myRoot.Position - entry.Root.Position).Magnitude
        if dist > cfg.MaxDistance then continue end
        if cfg.FOVEnabled and not asInFOV(entry.Head.Position) then continue end
        if cfg.VisibleOnly and not asIsVisible(myRoot.Position, entry.Head.Position, entry.Model) then
            continue
        end
        local score
        if cfg.FOVEnabled then
            local vp = archWs.CurrentCamera:WorldToViewportPoint(entry.Head.Position)
            score = (Vector2.new(vp.X, vp.Y) - center).Magnitude
        else
            score = dist
        end
        if score < bestScore then
            bestScore = score
            best = entry
        end
    end
    if best and cfg.TargetLock then asLockedEntry = best end
    return best
end

local function asFireAt(entry, localFighter)
    if not archUtil or not archEnums then return end
    local cfg     = getgenv().ASCfg
    local hitPart = asResolveHitPart(entry)
    if not hitPart then return end
    local targetPos = asPredictedPos(entry, hitPart)
    local sp = cfg.Spread
    local offset = Vector3.new(
        (math.random() - 0.5) * sp,
        (math.random() - 0.5) * sp,
        (math.random() - 0.5) * sp)
    local aimedPos  = targetPos + offset
    local originPos = aimedPos + Vector3.new(0, 1, 0)
    local aimCF     = CFrame.lookAt(originPos, aimedPos)
    local targetCF  = hitPart.CFrame
    local objOffset = hitPart.CFrame:ToObjectSpace(CFrame.new(aimedPos))
    local cameradata = {}
    cameradata[utf8.char(1)] = {
        [utf8.char(0)] = archUtil:EncodeCFrame(aimCF),
        [utf8.char(1)] = archUtil:EncodeCFrame(targetCF),
        [utf8.char(2)] = hitPart,
        [utf8.char(3)] = archUtil:EncodeCFrame(objOffset),
    }
    pcall(function()
        archRepS.Remotes.Replication.Fighter.UseItem:FireServer(
            localFighter.EquippedItem:Get("ObjectID"),
            archEnums:ToEnum("StartShooting"),
            cameradata,
            nil
        )
    end)
end

task.spawn(function()
    while true do
        task.wait(0.1)
        if not getgenv().ASCfg.Enabled then continue end
        local lf = archFighters and archFighters.LocalFighter
        if lf and lf.EquippedItem == nil then
            pcall(function() lf:EquipItem(asGetSlotNumber()) end)
        end
    end
end)

local asLastFire = 0
local asHbConn
asHbConn = svc.RunService.Heartbeat:Connect(function()
    local cfg = getgenv().ASCfg
    if not cfg.Enabled then return end
    local char = archPlayer.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then return end
    local lf = archFighters and archFighters.LocalFighter
    if not lf or not lf.EquippedItem then return end
    local now = os.clock()
    if now - asLastFire < cfg.FireRate then return end
    local entry = asGetBestTarget()
    if not entry then return end
    asLastFire = now
    if cfg.BurstEnabled then
        task.spawn(function()
            for i = 1, cfg.BurstCount do
                if not cfg.Enabled then break end
                asFireAt(entry, lf)
                if i < cfg.BurstCount then task.wait(cfg.BurstDelay) end
            end
        end)
    else
        asFireAt(entry, lf)
    end
end)

_G.__ARCH_HELPERS.asTargetCache   = asTargetCache
_G.__ARCH_HELPERS.asRebuildCache  = asRebuildCache
_G.__ARCH_HELPERS.asGetBestTarget = asGetBestTarget
_G.__ARCH_HELPERS.asFireAt        = asFireAt
_G.__ARCH_HELPERS.asHbConn        = asHbConn
_G.__ARCH_HELPERS.asLastFire      = function() return asLastFire end
_G.__ARCH_HELPERS.asLockedEntry   = function(v)
    if v ~= nil then asLockedEntry = v end
    return asLockedEntry
end
