-- ▼▼▼ Step 6.1 conflict detector and unload hooks
-- conflict detector: prevent running two engines that fight over UseItem.FireServer
local archConflicts = {
    { name = 'Flickbot rage + Ragebot',  check = function()
        return archRageCfg.Active and archRagebotSettings.on
    end },
    { name = 'Ragebot + HvH',           check = function()
        return archRagebotSettings.on and getgenv().HvhCfg.Enabled
    end },
    { name = 'Ragebot + Auto-Shoot',    check = function()
        return archRagebotSettings.on and getgenv().ASCfg.Enabled
    end },
    { name = 'Flickbot rage + HvH',     check = function()
        return archRageCfg.Active and getgenv().HvhCfg.Enabled
    end },
    { name = 'Flickbot rage + Auto-Shoot', check = function()
        return archRageCfg.Active and getgenv().ASCfg.Enabled
    end },
    { name = 'HvH + Auto-Shoot',        check = function()
        return getgenv().HvhCfg.Enabled and getgenv().ASCfg.Enabled
    end },
}

local archConflictLast = nil
task.spawn(function()
    while true do
        task.wait(1)
        local active = {}
        for _, c in ipairs(archConflicts) do
            local ok, result = pcall(c.check)
            if ok and result then table.insert(active, c.name) end
        end
        local summary = #active > 0 and table.concat(active, ' | ') or nil
        if summary ~= archConflictLast then
            archConflictLast = summary
            if summary then
                pcall(context.ui.notify, 'CONFLICT: ' .. summary)
                warn('[arch legacy] engine conflict: ' .. summary)
            end
        end
    end
end)

_G.__ARCH_HELPERS.archConflicts = archConflicts

-- unload hooks: clean up every RenderStep, connection, restore root
context.scope:add(function()
    -- stop ragebot if active
    pcall(function()
        if _G.__ARCH_HELPERS.stopRagebot then
            _G.__ARCH_HELPERS.stopRagebot()
        end
    end)
    -- stop flickbot and rage
    archFlickCfg.Active = false
    archRageCfg.Active   = false
    -- stop hvh
    getgenv().HvhCfg.Enabled = false
    pcall(hvhKnifeStopLoop)
    -- stop auto-shoot
    getgenv().ASCfg.Enabled = false
    -- disconnect flickbot heartbeat
    pcall(function()
        if archFlickbotConn then
            archFlickbotConn:Disconnect()
            archFlickbotConn = nil
        end
    end)
    -- disconnect hvh stepped loop
    pcall(function()
        if _G.__ARCH_HELPERS.hvhHbConn then
            _G.__ARCH_HELPERS.hvhHbConn:Disconnect()
        end
    end)
    -- disconnect auto-shoot heartbeat
    pcall(function()
        if _G.__ARCH_HELPERS.asHbConn then
            _G.__ARCH_HELPERS.asHbConn:Disconnect()
        end
    end)
    -- unbind every RenderStep the legacy engines may have bound
    for _, name in ipairs({
        '__arch_flickbot_restore',
        '__arch_hvh_restore',
        '__arch_hvh_knife_restore',
    }) do
        pcall(function()
            svc.RunService:UnbindFromRenderStep(name)
        end)
    end
    -- restore local root if a desync left it in a weird spot
    pcall(function()
        local char = archPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local st   = _G.__ARCH_HELPERS.rbActiveState()
        if root and st and st.csyncLocalCF then
            root.CFrame = st.csyncLocalCF
            root.AssemblyLinearVelocity  = st.csyncLocalLV or Vector3.zero
            root.AssemblyAngularVelocity = st.csyncLocalAV or Vector3.zero
        end
    end)
    -- restore collision on every BasePart
    pcall(function()
        local char = archPlayer.Character
        if char then
            for _, part in char:GetDescendants() do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
        end
    end)
    -- restore KnifeItem.StartAiming if it was hooked
    pcall(function()
        local ps = archPlayer:FindFirstChild("PlayerScripts")
        local ms = ps and ps:FindFirstChild("Modules")
        local it = ms and ms:FindFirstChild("Items")
        local kn = it and it:FindFirstChild("Knife")
        if kn then
            local ok, m = pcall(require, kn)
            if ok and m and m.StartAiming and m._archOriginalStartAiming then
                m.StartAiming = m._archOriginalStartAiming
                m._archOriginalStartAiming = nil
            end
        end
    end)
    -- status bar Gui
    pcall(function()
        if rbStatusGui and rbStatusGui.Parent then
            rbStatusGui:Destroy()
        end
    end)
    -- stop all background state loops implicitly by setting Enabled = false
    warn('[arch legacy] all engines stopped and resources released')
end)
