local _fuServices = __ANTIBRAIN_MODULES.k()
local _fuPlayers  = _fuServices.Players
local _fuRun      = _fuServices.RunService
local _fuRS       = _fuServices.ReplicatedStorage
local _fuLP       = _fuPlayers.LocalPlayer

local FU = {
    on=false, depth=5.8, walk=true, hide=true,
    camera=false, noclip=true, anim=true, zeroVel=true,
    panic=false, pMin=-5, pMax=5, pYMin=0, pYMax=0, pZ=false, pZMin=-5, pZMax=5,
    rage=false, orbit=false, radius=14, speed=4, rate=0.1,
    slot='Primary', maxDist=400, team=true,
    ang=0, target=nil, lastShot=0,
    localCF=nil, virtualCF=nil, saved=nil, track=nil, hb=nil,
}

local function _fuHideChar()
    local char = _fuLP.Character; if not char then return end
    FU.saved = {}
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA('BasePart') or part:IsA('Decal') then
            FU.saved[#FU.saved+1] = {part=part, t=part.Transparency}
            pcall(function() part.Transparency = 1 end)
        end
    end
end

local function _fuShowChar()
    if not FU.saved then return end
    for _, d in ipairs(FU.saved) do
        if d.part and d.part.Parent then
            pcall(function() d.part.Transparency = d.t end)
        end
    end
    FU.saved = nil
end

local function _fuStartAnim()
    local hum = _fuLP.Character and _fuLP.Character:FindFirstChildOfClass('Humanoid')
    if not hum or FU.track then return end
    pcall(function()
        local a = Instance.new('Animation')
        a.AnimationId = 'rbxassetid://10714003221'
        local t = hum:LoadAnimation(a)
        t:Play(0, 1, 0); t.TimePosition = 1.48
        FU.track = t
    end)
end

local function _fuStopAnim()
    if FU.track then
        pcall(function() FU.track:Stop(); FU.track:Destroy() end)
        FU.track = nil
    end
end
