local _fuMods, _fuModErr = nil, nil
local function _fuGetMods()
    if _fuMods then return _fuMods end
    local ok, res = pcall(function()
        return {
            util    = require(_fuRS.Modules.Utility),
            enumLib = require(_fuRS.Modules.EnumLibrary),
            FC      = require(_fuLP.PlayerScripts.Controllers.FighterController),
        }
    end)
    if ok then _fuMods = res; _fuModErr = nil
    else _fuModErr = tostring(res) end
    return _fuMods
end

local _fuSlotIdx = { Primary=1, Secondary=2, Melee=3 }

local function _fuValidTarget(plr, myPos)
    if plr == _fuLP then return nil end
    if FU.team and plr.Team ~= nil and plr.Team == _fuLP.Team then return nil end
    local ch   = plr.Character
    local root = ch and ch:FindFirstChild('HumanoidRootPart')
    local head = ch and ch:FindFirstChild('Head')
    local hum  = ch and ch:FindFirstChildOfClass('Humanoid')
    if not (root and head and hum) or hum.Health <= 0 then return nil end
    if root.Position.Y < -500 or root.Position.Y > 2000 then return nil end
    local d = (root.Position - myPos).Magnitude
    if d > FU.maxDist then return nil end
    return root, head, d
end

local function _fuPickTarget(myPos)
    local cur = FU.target
    if cur and cur.plr and cur.plr.Parent then
        local root, head = _fuValidTarget(cur.plr, myPos)
        if root then cur.root, cur.head = root, head; return cur end
    end
    local best, bestD = nil, math.huge
    for _, plr in ipairs(_fuPlayers:GetPlayers()) do
        local root, head, d = _fuValidTarget(plr, myPos)
        if root and d < bestD then
            bestD = d
            best = { plr=plr, root=root, head=head }
        end
    end
    FU.target = best
    return best
end

local function _fuShootAt(head, fromPos)
    local m = _fuGetMods(); if not m then return false end
    local lf = m.FC.LocalFighter; if not lf then return false end
    if lf.EquippedItem == nil then
        pcall(function() lf:EquipItem(_fuSlotIdx[FU.slot] or 1) end)
        return false
    end
    local hp    = head.Position
    local aimCF = CFrame.lookAt(fromPos + Vector3.new(0, 1.5, 0), hp)
    local objSp = head.CFrame:ToObjectSpace(CFrame.new(hp))
    local data  = {}
    data[utf8.char(1)] = {
        [utf8.char(0)] = m.util:EncodeCFrame(aimCF),
        [utf8.char(1)] = m.util:EncodeCFrame(head.CFrame),
        [utf8.char(2)] = head,
        [utf8.char(3)] = m.util:EncodeCFrame(objSp),
    }
    return pcall(function()
        _fuRS.Remotes.Replication.Fighter.UseItem:FireServer(
            lf.EquippedItem:Get('ObjectID'),
            m.enumLib:ToEnum('StartShooting'),
            data, nil
        )
    end)
end

local function _fuTurnOff()
    FU.on = false; FU.localCF = nil; FU.target = nil
    pcall(function() _fuRun:UnbindFromRenderStep('FU_OrbitUndo') end)
    if FU.hb then FU.hb:Disconnect(); FU.hb = nil end
    pcall(function() _fuRun:UnbindFromRenderStep('FU_SurfaceCamera') end)
    _fuShowChar(); _fuStopAnim()
    local hrp = _fuLP.Character and _fuLP.Character:FindFirstChild('HumanoidRootPart')
    if hrp and FU.virtualCF then
        pcall(function()
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.CFrame = FU.virtualCF
        end)
    end
    FU.virtualCF = nil
end

local function _fuTurnOn()
    FU.on = true
    local hrp = _fuLP.Character and _fuLP.Character:FindFirstChild('HumanoidRootPart')
    if hrp then FU.virtualCF = hrp.CFrame end
    if FU.hide then _fuHideChar() end
    if FU.anim then _fuStartAnim() end

    pcall(function() _fuRun:UnbindFromRenderStep('FU_SurfaceCamera') end)
    _fuRun:BindToRenderStep('FU_SurfaceCamera', 201, function()
        if FU.on and FU.camera then
            local cam = workspace.CurrentCamera
            if cam and FU.depth > 0 then
                cam.CFrame = cam.CFrame + Vector3.new(0, FU.depth, 0)
            end
        end
    end)

    pcall(function() _fuRun:UnbindFromRenderStep('FU_OrbitUndo') end)
    _fuRun:BindToRenderStep('FU_OrbitUndo', Enum.RenderPriority.Camera.Value - 1, function()
        if FU.on and FU.localCF then
            local h = _fuLP.Character and _fuLP.Character:FindFirstChild('HumanoidRootPart')
            if h then h.CFrame = FU.localCF end
        end
    end)

    FU.hb = _fuRun.Heartbeat:Connect(function(dt)
        if not FU.on then return end
        local char = _fuLP.Character
        local hrp2 = char and char:FindFirstChild('HumanoidRootPart')
        local hum  = char and char:FindFirstChildOfClass('Humanoid')
        if not hrp2 or not hum then return end

        local cam  = workspace.CurrentCamera
        local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
        local rot  = CFrame.Angles(0, math.atan2(-look.X, -look.Z), 0)

        if not FU.virtualCF then FU.virtualCF = CFrame.new(hrp2.Position) * rot end
        local pos = FU.virtualCF.Position
        if FU.walk and hum.MoveDirection.Magnitude > 0 then
            pos = pos + hum.MoveDirection * (hum.WalkSpeed * dt)
        end
        FU.virtualCF = CFrame.new(pos) * rot

        local under = pos - Vector3.new(0, FU.depth, 0)
                if FU.panic then
            local loX = math.min(FU.pMin,  FU.pMax)
            local hiX = math.max(FU.pMin,  FU.pMax)
            local jx  = loX + math.random() * (hiX - loX)
            local loY = math.min(FU.pYMin, FU.pYMax)
            local hiY = math.max(FU.pYMin, FU.pYMax)
            local jy  = loY + math.random() * (hiY - loY)
            local loZ = math.min(FU.pZMin, FU.pZMax)
            local hiZ = math.max(FU.pZMin, FU.pZMax)
            local jz  = FU.pZ and (loZ + math.random() * (hiZ - loZ)) or 0
            under = under + Vector3.new(jx, jy, jz)
        end

        if FU.noclip then
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA('BasePart') and p.CanCollide then p.CanCollide = false end
            end
        end
        if FU.zeroVel then
            hrp2.AssemblyLinearVelocity  = Vector3.zero
            hrp2.AssemblyAngularVelocity = Vector3.zero
        end

        local localCF = CFrame.new(under) * rot
        FU.localCF = nil

        if FU.rage then
            local tgt = _fuPickTarget(pos)
            if tgt and not FU.orbit then
                hrp2.CFrame = localCF
                if tick() - FU.lastShot >= FU.rate then
                    FU.lastShot = tick()
                    _fuShootAt(tgt.head, localCF.Position)
                end
            elseif tgt then
                FU.ang = (FU.ang + FU.speed * dt) % (math.pi * 2)
                local tp = tgt.root.Position
                local orbitPos = Vector3.new(
                    tp.X + math.cos(FU.ang) * FU.radius,
                    tp.Y - FU.depth,
                    tp.Z + math.sin(FU.ang) * FU.radius
                )
                local yaw = CFrame.new(orbitPos) * CFrame.Angles(
                    0,
                    math.atan2(-(tp.X - orbitPos.X), -(tp.Z - orbitPos.Z)),
                    0
                )
                FU.localCF  = localCF
                hrp2.CFrame = yaw
                if tick() - FU.lastShot >= FU.rate then
                    FU.lastShot = tick()
                    _fuShootAt(tgt.head, orbitPos)
                end
            else
                hrp2.CFrame = localCF
            end
        else
            hrp2.CFrame = localCF
        end

        if FU.hide and FU.saved then
            for _, d in ipairs(FU.saved) do
                if d.part and d.part.Parent and d.part.Transparency ~= 1 then
                    pcall(function() d.part.Transparency = 1 end)
                end
            end
        end
    end)

    _fuLP.CharacterAdded:Connect(function()
        if FU.on then task.wait(1); _fuTurnOff(); _fuTurnOn() end
    end)
end
