local _auBypFields = {
    Gun   = { ShootSpread=0, ShootAccuracy=0, ShootRecoil=0, ShootCooldown=0.001, ShootBurstCooldown=0.001 },
    Melee = { AttackCooldown=0.001, SwingCooldown=0.001, MeleeCooldown=0.001, Cooldown=0.001, RecoveryTime=0.001, ResetTime=0.001 },
}

local function _auGetItems()
    if not _auItemLib then
        local ok, r = pcall(function() return require(_auRepSto.Modules.ItemLibrary).Items end)
        _auItemLib = (ok and r) or {}
    end
    return _auItemLib
end

function AU.setBypass(kind, enable)
    local fields = _auBypFields[kind]; if not fields then return end
    for _, item in pairs(_auGetItems()) do
        if typeof(item) == 'table' then
            for f, val in pairs(fields) do
                if enable then
                    if item[f] ~= nil then
                        _auBackup[item] = _auBackup[item] or {}
                        if _auBackup[item][f] == nil then _auBackup[item][f] = item[f] end
                        item[f] = val
                    end
                else
                    local orig = _auBackup[item] and _auBackup[item][f]
                    if orig ~= nil then item[f] = orig end
                end
            end
        end
    end
end
